tb_script:
#!/bin/bash
set -uo pipefail

cd /home/cva6 || exit 1

TEST_NAME="csr_mie_embedded_mask"
TB_DIR="/home/cva6/.tb_${TEST_NAME}"
VERILATOR_BIN="/home/cva6/.hwe_tools/verilator/bin/verilator"
BUILD_LOG="${TB_DIR}/verilate.log"
RUN_LOG="${TB_DIR}/run.log"

rm -rf "${TB_DIR}"
mkdir -p "${TB_DIR}/build"

cat > "${TB_DIR}/tb.sv" <<'EOF'
`include "rvfi_types.svh"

module csr_mie_embedded_tb;
  import ariane_pkg::*;

  localparam config_pkg::cva6_cfg_t CVA6Cfg = build_config_pkg::build_config(cva6_config_pkg::cva6_cfg);
  localparam type rvfi_probes_csr_t = `RVFI_PROBES_CSR_T(CVA6Cfg);

  localparam type branchpredict_sbe_t = struct packed {
    cf_t                     cf;
    logic [CVA6Cfg.VLEN-1:0] predict_address;
  };

  localparam type exception_t = struct packed {
    logic [CVA6Cfg.XLEN-1:0]  cause;
    logic [CVA6Cfg.XLEN-1:0]  tval;
    logic [CVA6Cfg.GPLEN-1:0] tval2;
    logic [31:0]              tinst;
    logic                     gva;
    logic                     valid;
  };

  localparam type scoreboard_entry_t = struct packed {
    logic [CVA6Cfg.VLEN-1:0]          pc;
    logic [CVA6Cfg.TRANS_ID_BITS-1:0] trans_id;
    fu_t                              fu;
    fu_op                             op;
    logic [REG_ADDR_SIZE-1:0]         rs1;
    logic [REG_ADDR_SIZE-1:0]         rs2;
    logic [REG_ADDR_SIZE-1:0]         rd;
    logic [CVA6Cfg.XLEN-1:0]          result;
    logic                             valid;
    logic                             use_imm;
    logic                             use_zimm;
    logic                             use_pc;
    exception_t                       ex;
    branchpredict_sbe_t               bp;
    logic                             is_compressed;
    logic                             is_macro_instr;
    logic                             is_last_macro_instr;
    logic                             is_double_rd_macro_instr;
    logic                             vfp;
  };

  localparam type irq_ctrl_t = struct packed {
    logic [CVA6Cfg.XLEN-1:0] mie;
    logic [CVA6Cfg.XLEN-1:0] mip;
    logic [CVA6Cfg.XLEN-1:0] mideleg;
    logic [CVA6Cfg.XLEN-1:0] hideleg;
    logic                    sie;
    logic                    global_enable;
  };

  logic clk_i;
  logic rst_ni;
  logic time_irq_i;
  logic flush_o;
  logic halt_csr_o;
  scoreboard_entry_t [CVA6Cfg.NrCommitPorts-1:0] commit_instr_i;
  logic [CVA6Cfg.NrCommitPorts-1:0] commit_ack_i;
  logic [CVA6Cfg.VLEN-1:0] boot_addr_i;
  logic [CVA6Cfg.XLEN-1:0] hart_id_i;
  exception_t ex_i;
  fu_op csr_op_i;
  logic [11:0] csr_addr_i;
  logic [CVA6Cfg.XLEN-1:0] csr_wdata_i;
  logic [CVA6Cfg.XLEN-1:0] csr_rdata_o;
  logic dirty_fp_state_i;
  logic csr_write_fflags_i;
  logic dirty_v_state_i;
  logic [CVA6Cfg.VLEN-1:0] pc_i;
  exception_t csr_exception_o;
  logic [CVA6Cfg.VLEN-1:0] epc_o;
  logic eret_o;
  logic [CVA6Cfg.VLEN-1:0] trap_vector_base_o;
  riscv::priv_lvl_t priv_lvl_o;
  logic v_o;
  logic [4:0] acc_fflags_ex_i;
  logic acc_fflags_ex_valid_i;
  riscv::xs_t fs_o;
  riscv::xs_t vfs_o;
  logic [4:0] fflags_o;
  logic [2:0] frm_o;
  logic [6:0] fprec_o;
  riscv::xs_t vs_o;
  irq_ctrl_t irq_ctrl_o;
  logic en_translation_o;
  logic en_g_translation_o;
  logic en_ld_st_translation_o;
  logic en_ld_st_g_translation_o;
  riscv::priv_lvl_t ld_st_priv_lvl_o;
  logic ld_st_v_o;
  logic csr_hs_ld_st_inst_i;
  logic sum_o;
  logic vs_sum_o;
  logic mxr_o;
  logic vmxr_o;
  logic [CVA6Cfg.PPNW-1:0] satp_ppn_o;
  logic [CVA6Cfg.ASID_WIDTH-1:0] asid_o;
  logic [CVA6Cfg.PPNW-1:0] vsatp_ppn_o;
  logic [CVA6Cfg.ASID_WIDTH-1:0] vs_asid_o;
  logic [CVA6Cfg.PPNW-1:0] hgatp_ppn_o;
  logic [CVA6Cfg.VMID_WIDTH-1:0] vmid_o;
  logic [1:0] irq_i;
  logic ipi_i;
  logic debug_req_i;
  logic set_debug_pc_o;
  logic tvm_o;
  logic tw_o;
  logic vtw_o;
  logic tsr_o;
  logic hu_o;
  logic debug_mode_o;
  logic single_step_o;
  logic icache_en_o;
  logic dcache_en_o;
  logic acc_cons_en_o;
  logic [11:0] perf_addr_o;
  logic [CVA6Cfg.XLEN-1:0] perf_data_o;
  logic [CVA6Cfg.XLEN-1:0] perf_data_i;
  logic perf_we_o;
  riscv::pmpcfg_t [15:0] pmpcfg_o;
  logic [15:0][CVA6Cfg.PLEN-3:0] pmpaddr_o;
  logic [31:0] mcountinhibit_o;
  rvfi_probes_csr_t rvfi_csr_o;

  csr_regfile #(
    .CVA6Cfg(CVA6Cfg),
    .exception_t(exception_t),
    .irq_ctrl_t(irq_ctrl_t),
    .scoreboard_entry_t(scoreboard_entry_t),
    .rvfi_probes_csr_t(rvfi_probes_csr_t)
  ) dut (
    .*
  );

  task automatic half_cycle;
    #5 clk_i = ~clk_i;
  endtask

  task automatic full_cycle;
    begin
      half_cycle();
      half_cycle();
    end
  endtask

  task automatic drive_idle;
    begin
      csr_op_i = ADD;
      csr_addr_i = '0;
      csr_wdata_i = '0;
      commit_ack_i = '0;
      ex_i = '0;
    end
  endtask

  task automatic csr_write(input logic [11:0] addr, input logic [CVA6Cfg.XLEN-1:0] data);
    begin
      csr_addr_i = addr;
      csr_wdata_i = data;
      csr_op_i = CSR_WRITE;
      full_cycle();
      drive_idle();
    end
  endtask

  task automatic csr_read(input logic [11:0] addr, output logic [CVA6Cfg.XLEN-1:0] data);
    begin
      csr_addr_i = addr;
      csr_op_i = CSR_READ;
      #1;
      data = csr_rdata_o;
      #1;
      full_cycle();
      drive_idle();
    end
  endtask

  task automatic expect_eq(
    input string name,
    input logic [CVA6Cfg.XLEN-1:0] actual,
    input logic [CVA6Cfg.XLEN-1:0] expected
  );
    begin
      if (actual !== expected) begin
        $display("CHECK %s actual=0x%08x expected=0x%08x", name, actual, expected);
        $fatal(1, "Mismatch for %s", name);
      end
    end
  endtask

  logic [CVA6Cfg.XLEN-1:0] readback;

  initial begin
    clk_i = 1'b0;
    rst_ni = 1'b0;
    time_irq_i = 1'b0;
    boot_addr_i = 'h8000_0000;
    hart_id_i = '0;
    dirty_fp_state_i = 1'b0;
    csr_write_fflags_i = 1'b0;
    dirty_v_state_i = 1'b0;
    pc_i = '0;
    acc_fflags_ex_i = '0;
    acc_fflags_ex_valid_i = 1'b0;
    csr_hs_ld_st_inst_i = 1'b0;
    irq_i = '0;
    ipi_i = 1'b0;
    debug_req_i = 1'b0;
    perf_data_i = '0;
    commit_instr_i = '{default: '0};
    drive_idle();

    repeat (4) full_cycle();
    rst_ni = 1'b1;
    repeat (4) full_cycle();

    csr_write(12'h304, '0);
    csr_read(12'h304, readback);
    expect_eq("mie_reset", readback, '0);

    csr_write(12'h304, 32'h0000_0888);
    csr_read(12'h304, readback);
    expect_eq("mie_machine_bits", readback, 32'h0000_0888);

    csr_write(12'h304, '0);
    csr_write(12'h304, 32'h0000_0222);
    csr_read(12'h304, readback);
    expect_eq("mie_supervisor_bits", readback, 32'h0000_0000);

    csr_write(12'h304, '0);
    csr_write(12'h304, 32'h0000_0aaa);
    csr_read(12'h304, readback);
    expect_eq("mie_masked_write", readback, 32'h0000_0888);

    if (csr_exception_o.valid) begin
      $fatal(1, "Unexpected csr_exception_o.valid");
    end

    $display("CSR MIE embedded test passed");
    $finish;
  end
endmodule
EOF

if [[ ! -x "${VERILATOR_BIN}" ]]; then
  echo "[ERROR] Missing Verilator binary at ${VERILATOR_BIN}"
  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: ${TEST_NAME} ... FAIL"
  echo "HWE_BENCH_RESULTS_END"
  exit 1
fi

set +e
"${VERILATOR_BIN}" --binary --timing --assert \
  -Wall \
  -Wno-fatal \
  -Wno-DECLFILENAME \
  -Wno-VARHIDDEN \
  -Wno-WIDTHTRUNC \
  -Wno-WIDTHEXPAND \
  -Wno-UNUSEDSIGNAL \
  -Wno-UNUSEDPARAM \
  -Wno-LATCH \
  -Wno-SYNCASYNCNET \
  -I/home/cva6/core/include \
  /home/cva6/core/include/config_pkg.sv \
  /home/cva6/core/include/cv32a6_embedded_config_pkg.sv \
  /home/cva6/core/include/riscv_pkg.sv \
  /home/cva6/core/include/ariane_pkg.sv \
  /home/cva6/core/include/build_config_pkg.sv \
  /home/cva6/core/csr_regfile.sv \
  "${TB_DIR}/tb.sv" \
  --top-module csr_mie_embedded_tb \
  --Mdir "${TB_DIR}/build" >"${BUILD_LOG}" 2>&1
build_rc=$?

run_rc=0
if [[ ${build_rc} -eq 0 ]]; then
  "${TB_DIR}/build/Vcsr_mie_embedded_tb" >"${RUN_LOG}" 2>&1
  run_rc=$?
fi
set -e

if [[ -f "${BUILD_LOG}" ]]; then
  cat "${BUILD_LOG}"
fi
if [[ -f "${RUN_LOG}" ]]; then
  cat "${RUN_LOG}"
fi

final_rc=0
if [[ ${build_rc} -ne 0 ]]; then
  final_rc=${build_rc}
elif [[ ${run_rc} -ne 0 ]]; then
  final_rc=${run_rc}
fi

echo "HWE_BENCH_RESULTS_START"
if [[ ${final_rc} -eq 0 ]]; then
  echo "TEST: ${TEST_NAME} ... PASS"
else
  echo "TEST: ${TEST_NAME} ... FAIL"
fi
echo "HWE_BENCH_RESULTS_END"

exit "${final_rc}"

#!/bin/bash
cd /home/cva6 || exit 1
set -uo pipefail

TB_DIR=/home/cva6/.tb_zexth_decoder
overall_rc=0

unset VERILATOR_ROOT
unset VERILATOR_BIN

if [ -x /tools/verilator/bin/verilator ]; then
  VERILATOR=/tools/verilator/bin/verilator
elif command -v verilator >/dev/null 2>&1; then
  VERILATOR=$(command -v verilator)
else
  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: decoder_zexth_rv64 ... FAIL"
  echo "TEST: decoder_zexth_rv32 ... FAIL"
  echo "HWE_BENCH_RESULTS_END"
  exit 1
fi

mkdir -p "$TB_DIR"

cat > "$TB_DIR/tb_rv64.sv" <<'EOF_RV64'
module tb_rv64;
  function automatic config_pkg::cva6_user_cfg_t disable_cvxif(input config_pkg::cva6_user_cfg_t cfg_in);
    disable_cvxif = cfg_in;
    disable_cvxif.CvxifEn = 1'b0;
  endfunction

  localparam config_pkg::cva6_cfg_t CVA6Cfg = build_config_pkg::build_config(
      disable_cvxif(cva6_config_pkg::cva6_cfg)
  );

  typedef struct packed {
    ariane_pkg::cf_t cf;
    logic [CVA6Cfg.VLEN-1:0] predict_address;
  } branchpredict_sbe_t;

  typedef struct packed {
    logic [CVA6Cfg.XLEN-1:0] cause;
    logic [CVA6Cfg.XLEN-1:0] tval;
    logic [CVA6Cfg.GPLEN-1:0] tval2;
    logic [31:0] tinst;
    logic gva;
    logic valid;
  } exception_t;

  typedef struct packed {
    logic [CVA6Cfg.XLEN-1:0] mie;
    logic [CVA6Cfg.XLEN-1:0] mip;
    logic [CVA6Cfg.XLEN-1:0] mideleg;
    logic [CVA6Cfg.XLEN-1:0] hideleg;
    logic sie;
    logic global_enable;
  } irq_ctrl_t;

  typedef struct packed {
    logic [CVA6Cfg.XLEN-1:0] S_SW;
    logic [CVA6Cfg.XLEN-1:0] VS_SW;
    logic [CVA6Cfg.XLEN-1:0] M_SW;
    logic [CVA6Cfg.XLEN-1:0] S_TIMER;
    logic [CVA6Cfg.XLEN-1:0] VS_TIMER;
    logic [CVA6Cfg.XLEN-1:0] M_TIMER;
    logic [CVA6Cfg.XLEN-1:0] S_EXT;
    logic [CVA6Cfg.XLEN-1:0] VS_EXT;
    logic [CVA6Cfg.XLEN-1:0] M_EXT;
    logic [CVA6Cfg.XLEN-1:0] HS_EXT;
  } interrupts_t;

  typedef struct packed {
    logic [CVA6Cfg.VLEN-1:0] pc;
    logic [CVA6Cfg.TRANS_ID_BITS-1:0] trans_id;
    ariane_pkg::fu_t fu;
    ariane_pkg::fu_op op;
    logic [ariane_pkg::REG_ADDR_SIZE-1:0] rs1;
    logic [ariane_pkg::REG_ADDR_SIZE-1:0] rs2;
    logic [ariane_pkg::REG_ADDR_SIZE-1:0] rd;
    logic [CVA6Cfg.XLEN-1:0] result;
    logic valid;
    logic use_imm;
    logic use_zimm;
    logic use_pc;
    exception_t ex;
    branchpredict_sbe_t bp;
    logic is_compressed;
    logic is_macro_instr;
    logic is_last_macro_instr;
    logic is_double_rd_macro_instr;
    logic vfp;
  } scoreboard_entry_t;

  localparam interrupts_t INTERRUPTS = '{
    S_SW: (1 << (CVA6Cfg.XLEN - 1)) | CVA6Cfg.XLEN'(riscv::IRQ_S_SOFT),
    VS_SW: (1 << (CVA6Cfg.XLEN - 1)) | CVA6Cfg.XLEN'(riscv::IRQ_VS_SOFT),
    M_SW: (1 << (CVA6Cfg.XLEN - 1)) | CVA6Cfg.XLEN'(riscv::IRQ_M_SOFT),
    S_TIMER: (1 << (CVA6Cfg.XLEN - 1)) | CVA6Cfg.XLEN'(riscv::IRQ_S_TIMER),
    VS_TIMER: (1 << (CVA6Cfg.XLEN - 1)) | CVA6Cfg.XLEN'(riscv::IRQ_VS_TIMER),
    M_TIMER: (1 << (CVA6Cfg.XLEN - 1)) | CVA6Cfg.XLEN'(riscv::IRQ_M_TIMER),
    S_EXT: (1 << (CVA6Cfg.XLEN - 1)) | CVA6Cfg.XLEN'(riscv::IRQ_S_EXT),
    VS_EXT: (1 << (CVA6Cfg.XLEN - 1)) | CVA6Cfg.XLEN'(riscv::IRQ_VS_EXT),
    M_EXT: (1 << (CVA6Cfg.XLEN - 1)) | CVA6Cfg.XLEN'(riscv::IRQ_M_EXT),
    HS_EXT: (1 << (CVA6Cfg.XLEN - 1)) | CVA6Cfg.XLEN'(riscv::IRQ_HS_EXT)
  };

  logic debug_req_i;
  logic [CVA6Cfg.VLEN-1:0] pc_i;
  logic is_compressed_i;
  logic [15:0] compressed_instr_i;
  logic is_illegal_i;
  logic [31:0] instruction_i;
  logic is_macro_instr_i;
  logic is_last_macro_instr_i;
  logic is_double_rd_macro_instr_i;
  branchpredict_sbe_t branch_predict_i;
  exception_t ex_i;
  logic [1:0] irq_i;
  irq_ctrl_t irq_ctrl_i;
  riscv::priv_lvl_t priv_lvl_i;
  logic v_i;
  logic debug_mode_i;
  riscv::xs_t fs_i;
  riscv::xs_t vfs_i;
  logic [2:0] frm_i;
  riscv::xs_t vs_i;
  logic tvm_i;
  logic tw_i;
  logic vtw_i;
  logic tsr_i;
  logic hu_i;
  scoreboard_entry_t instruction_o;
  logic [31:0] orig_instr_o;
  logic is_control_flow_instr_o;

  decoder #(
    .CVA6Cfg(CVA6Cfg),
    .branchpredict_sbe_t(branchpredict_sbe_t),
    .exception_t(exception_t),
    .irq_ctrl_t(irq_ctrl_t),
    .scoreboard_entry_t(scoreboard_entry_t),
    .interrupts_t(interrupts_t),
    .INTERRUPTS(INTERRUPTS)
  ) dut (
    .debug_req_i(debug_req_i),
    .pc_i(pc_i),
    .is_compressed_i(is_compressed_i),
    .compressed_instr_i(compressed_instr_i),
    .is_illegal_i(is_illegal_i),
    .instruction_i(instruction_i),
    .is_macro_instr_i(is_macro_instr_i),
    .is_last_macro_instr_i(is_last_macro_instr_i),
    .is_double_rd_macro_instr_i(is_double_rd_macro_instr_i),
    .branch_predict_i(branch_predict_i),
    .ex_i(ex_i),
    .irq_i(irq_i),
    .irq_ctrl_i(irq_ctrl_i),
    .priv_lvl_i(priv_lvl_i),
    .v_i(v_i),
    .debug_mode_i(debug_mode_i),
    .fs_i(fs_i),
    .vfs_i(vfs_i),
    .frm_i(frm_i),
    .vs_i(vs_i),
    .tvm_i(tvm_i),
    .tw_i(tw_i),
    .vtw_i(vtw_i),
    .tsr_i(tsr_i),
    .hu_i(hu_i),
    .instruction_o(instruction_o),
    .orig_instr_o(orig_instr_o),
    .is_control_flow_instr_o(is_control_flow_instr_o)
  );

  initial begin
    debug_req_i = 1'b0;
    pc_i = '0;
    is_compressed_i = 1'b0;
    compressed_instr_i = '0;
    is_illegal_i = 1'b0;
    instruction_i = {7'b000_0100, 5'd0, 5'd3, 3'b100, 5'd2, riscv::OpcodeOp32};
    is_macro_instr_i = 1'b0;
    is_last_macro_instr_i = 1'b0;
    is_double_rd_macro_instr_i = 1'b0;
    branch_predict_i = '0;
    ex_i = '0;
    irq_i = '0;
    irq_ctrl_i = '0;
    priv_lvl_i = riscv::PRIV_LVL_M;
    v_i = 1'b0;
    debug_mode_i = 1'b0;
    fs_i = riscv::Off;
    vfs_i = riscv::Off;
    frm_i = '0;
    vs_i = riscv::Off;
    tvm_i = 1'b0;
    tw_i = 1'b0;
    vtw_i = 1'b0;
    tsr_i = 1'b0;
    hu_i = 1'b0;

    #1;

    if (instruction_o.op != ariane_pkg::ZEXTH) begin
      $error("Expected RV64 legal ZEXT.H to decode as ZEXTH, got op=%0d", instruction_o.op);
      $fatal(1);
    end
    if (instruction_o.ex.valid) begin
      $error("Expected RV64 legal ZEXT.H to stay legal, cause=%0d", instruction_o.ex.cause);
      $fatal(1);
    end

    $display("rv64 legal ZEXT.H decoded correctly");
    $finish;
  end
endmodule
EOF_RV64

cat > "$TB_DIR/tb_rv32.sv" <<'EOF_RV32'
module tb_rv32;
  function automatic config_pkg::cva6_user_cfg_t disable_cvxif(input config_pkg::cva6_user_cfg_t cfg_in);
    disable_cvxif = cfg_in;
    disable_cvxif.CvxifEn = 1'b0;
  endfunction

  localparam config_pkg::cva6_cfg_t CVA6Cfg = build_config_pkg::build_config(
      disable_cvxif(cva6_config_pkg::cva6_cfg)
  );

  typedef struct packed {
    ariane_pkg::cf_t cf;
    logic [CVA6Cfg.VLEN-1:0] predict_address;
  } branchpredict_sbe_t;

  typedef struct packed {
    logic [CVA6Cfg.XLEN-1:0] cause;
    logic [CVA6Cfg.XLEN-1:0] tval;
    logic [CVA6Cfg.GPLEN-1:0] tval2;
    logic [31:0] tinst;
    logic gva;
    logic valid;
  } exception_t;

  typedef struct packed {
    logic [CVA6Cfg.XLEN-1:0] mie;
    logic [CVA6Cfg.XLEN-1:0] mip;
    logic [CVA6Cfg.XLEN-1:0] mideleg;
    logic [CVA6Cfg.XLEN-1:0] hideleg;
    logic sie;
    logic global_enable;
  } irq_ctrl_t;

  typedef struct packed {
    logic [CVA6Cfg.XLEN-1:0] S_SW;
    logic [CVA6Cfg.XLEN-1:0] VS_SW;
    logic [CVA6Cfg.XLEN-1:0] M_SW;
    logic [CVA6Cfg.XLEN-1:0] S_TIMER;
    logic [CVA6Cfg.XLEN-1:0] VS_TIMER;
    logic [CVA6Cfg.XLEN-1:0] M_TIMER;
    logic [CVA6Cfg.XLEN-1:0] S_EXT;
    logic [CVA6Cfg.XLEN-1:0] VS_EXT;
    logic [CVA6Cfg.XLEN-1:0] M_EXT;
    logic [CVA6Cfg.XLEN-1:0] HS_EXT;
  } interrupts_t;

  typedef struct packed {
    logic [CVA6Cfg.VLEN-1:0] pc;
    logic [CVA6Cfg.TRANS_ID_BITS-1:0] trans_id;
    ariane_pkg::fu_t fu;
    ariane_pkg::fu_op op;
    logic [ariane_pkg::REG_ADDR_SIZE-1:0] rs1;
    logic [ariane_pkg::REG_ADDR_SIZE-1:0] rs2;
    logic [ariane_pkg::REG_ADDR_SIZE-1:0] rd;
    logic [CVA6Cfg.XLEN-1:0] result;
    logic valid;
    logic use_imm;
    logic use_zimm;
