    exception_t ex;
    branchpredict_sbe_t bp;
    logic is_compressed;
    logic is_macro_instr;
    logic is_last_macro_instr;
    logic is_double_rd_macro_instr;
    logic vfp;
  } scoreboard_entry_t;

  localparam interrupts_t INTERRUPTS = '{
    S_SW: (1 << (CVA6Cfg.XLEN - 1)) | CVA6Cfg.XLEN'(riscv::IRQ_S_SOFT),
    VS_SW: (1 << (CVA6Cfg.XLEN - 1)) | CVA6Cfg.XLEN'(riscv::IRQ_VS_SOFT),
    M_SW: (1 << (CVA6Cfg.XLEN - 1)) | CVA6Cfg.XLEN'(riscv::IRQ_M_SOFT),
    S_TIMER: (1 << (CVA6Cfg.XLEN - 1)) | CVA6Cfg.XLEN'(riscv::IRQ_S_TIMER),
    VS_TIMER: (1 << (CVA6Cfg.XLEN - 1)) | CVA6Cfg.XLEN'(riscv::IRQ_VS_TIMER),
    M_TIMER: (1 << (CVA6Cfg.XLEN - 1)) | CVA6Cfg.XLEN'(riscv::IRQ_M_TIMER),
    S_EXT: (1 << (CVA6Cfg.XLEN - 1)) | CVA6Cfg.XLEN'(riscv::IRQ_S_EXT),
    VS_EXT: (1 << (CVA6Cfg.XLEN - 1)) | CVA6Cfg.XLEN'(riscv::IRQ_VS_EXT),
    M_EXT: (1 << (CVA6Cfg.XLEN - 1)) | CVA6Cfg.XLEN'(riscv::IRQ_M_EXT),
    HS_EXT: (1 << (CVA6Cfg.XLEN - 1)) | CVA6Cfg.XLEN'(riscv::IRQ_HS_EXT)
  };

  logic debug_req_i;
  logic [CVA6Cfg.VLEN-1:0] pc_i;
  logic is_compressed_i;
  logic [15:0] compressed_instr_i;
  logic is_illegal_i;
  logic [31:0] instruction_i;
  logic is_macro_instr_i;
  logic is_last_macro_instr_i;
  logic is_double_rd_macro_instr_i;
  branchpredict_sbe_t branch_predict_i;
  exception_t ex_i;
  logic [1:0] irq_i;
  irq_ctrl_t irq_ctrl_i;
  riscv::priv_lvl_t priv_lvl_i;
  logic v_i;
  logic debug_mode_i;
  riscv::xs_t fs_i;
  riscv::xs_t vfs_i;
  logic [2:0] frm_i;
  riscv::xs_t vs_i;
  logic tvm_i;
  logic tw_i;
  logic vtw_i;
  logic tsr_i;
  logic hu_i;
  scoreboard_entry_t instruction_o;
  logic [31:0] orig_instr_o;
  logic is_control_flow_instr_o;

  decoder #(
    .CVA6Cfg(CVA6Cfg),
    .branchpredict_sbe_t(branchpredict_sbe_t),
    .exception_t(exception_t),
    .irq_ctrl_t(irq_ctrl_t),
    .scoreboard_entry_t(scoreboard_entry_t),
    .interrupts_t(interrupts_t),
    .INTERRUPTS(INTERRUPTS)
  ) dut (
    .debug_req_i(debug_req_i),
    .pc_i(pc_i),
    .is_compressed_i(is_compressed_i),
    .compressed_instr_i(compressed_instr_i),
    .is_illegal_i(is_illegal_i),
    .instruction_i(instruction_i),
    .is_macro_instr_i(is_macro_instr_i),
    .is_last_macro_instr_i(is_last_macro_instr_i),
    .is_double_rd_macro_instr_i(is_double_rd_macro_instr_i),
    .branch_predict_i(branch_predict_i),
    .ex_i(ex_i),
    .irq_i(irq_i),
    .irq_ctrl_i(irq_ctrl_i),
    .priv_lvl_i(priv_lvl_i),
    .v_i(v_i),
    .debug_mode_i(debug_mode_i),
    .fs_i(fs_i),
    .vfs_i(vfs_i),
    .frm_i(frm_i),
    .vs_i(vs_i),
    .tvm_i(tvm_i),
    .tw_i(tw_i),
    .vtw_i(vtw_i),
    .tsr_i(tsr_i),
    .hu_i(hu_i),
    .instruction_o(instruction_o),
    .orig_instr_o(orig_instr_o),
    .is_control_flow_instr_o(is_control_flow_instr_o)
  );

  task automatic expect_legal_zexth(input logic [31:0] instr_word, input string label);
    begin
      instruction_i = instr_word;
      #1;
      if (instruction_o.op != ariane_pkg::ZEXTH) begin
        $error("%s: expected ZEXTH decode, got op=%0d", label, instruction_o.op);
        $fatal(1);
      end
      if (instruction_o.ex.valid) begin
        $error("%s: expected legal decode, cause=%0d", label, instruction_o.ex.cause);
        $fatal(1);
      end
    end
  endtask

  task automatic expect_illegal(input logic [31:0] instr_word, input string label);
    begin
      instruction_i = instr_word;
      #1;
      if (!instruction_o.ex.valid || instruction_o.ex.cause != riscv::ILLEGAL_INSTR) begin
        $error("%s: expected illegal instruction exception, valid=%0d cause=%0d op=%0d",
               label, instruction_o.ex.valid, instruction_o.ex.cause, instruction_o.op);
        $fatal(1);
      end
    end
  endtask

  initial begin
    debug_req_i = 1'b0;
    pc_i = '0;
    is_compressed_i = 1'b0;
    compressed_instr_i = '0;
    is_illegal_i = 1'b0;
    instruction_i = '0;
    is_macro_instr_i = 1'b0;
    is_last_macro_instr_i = 1'b0;
    is_double_rd_macro_instr_i = 1'b0;
    branch_predict_i = '0;
    ex_i = '0;
    irq_i = '0;
    irq_ctrl_i = '0;
    priv_lvl_i = riscv::PRIV_LVL_M;
    v_i = 1'b0;
    debug_mode_i = 1'b0;
    fs_i = riscv::Off;
    vfs_i = riscv::Off;
    frm_i = '0;
    vs_i = riscv::Off;
    tvm_i = 1'b0;
    tw_i = 1'b0;
    vtw_i = 1'b0;
    tsr_i = 1'b0;
    hu_i = 1'b0;

    expect_legal_zexth({7'b000_0100, 5'd0, 5'd3, 3'b100, 5'd2, riscv::OpcodeOp},
                       "rv32_legal_zexth");
    expect_illegal({7'b000_0100, 5'd1, 5'd3, 3'b100, 5'd2, riscv::OpcodeOp},
                   "rv32_invalid_zexth_encoding");

    $display("rv32 ZEXT.H legality checks passed");
    $finish;
  end
endmodule
EOF_RV32

run_verilator_test() {
  local test_name="$1"
  local config_file="$2"
  local top_module="$3"
  local tb_file="$4"
  local mdir="$TB_DIR/$5"
  local build_log="$mdir/build.log"
  local run_log="$mdir/run.log"
  local rc=0

  rm -rf "$mdir"
  mkdir -p "$mdir"

  if "$VERILATOR" --binary --sv --timing --top-module "$top_module" \
      --Mdir "$mdir" -Wno-fatal -Icore/include \
      core/include/config_pkg.sv \
      "$config_file" \
      core/include/riscv_pkg.sv \
      core/include/ariane_pkg.sv \
      core/include/build_config_pkg.sv \
      core/cva6_accel_first_pass_decoder_stub.sv \
      core/decoder.sv \
      "$tb_file" >"$build_log" 2>&1; then
    if "$mdir/V$top_module" >"$run_log" 2>&1; then
      cat "$run_log"
      echo "TEST: $test_name ... PASS"
    else
      rc=$?
      cat "$build_log"
      cat "$run_log"
      echo "TEST: $test_name ... FAIL"
    fi
  else
    rc=$?
    cat "$build_log"
    echo "TEST: $test_name ... FAIL"
  fi

  if [ "$rc" -ne 0 ]; then
    overall_rc=1
  fi
}

echo "HWE_BENCH_RESULTS_START"
run_verilator_test "decoder_zexth_rv64" \
  "core/include/cv64a6_imafdc_sv39_config_pkg.sv" \
  "tb_rv64" \
  "$TB_DIR/tb_rv64.sv" \
  "obj_rv64"
run_verilator_test "decoder_zexth_rv32" \
  "core/include/cv32a60x_config_pkg.sv" \
  "tb_rv32" \
  "$TB_DIR/tb_rv32.sv" \
  "obj_rv32"
echo "HWE_BENCH_RESULTS_END"

exit "$overall_rc"

