#include <cstdint>
#include <iostream>

#include "Vdecoder_illegal_tb.h"
#include "verilated.h"

struct DecodeCase {
  const char* name;
  uint32_t instruction;
  bool expect_exception;
  uint32_t expect_cause;
};

int main(int argc, char** argv) {
  Verilated::commandArgs(argc, argv);

  Vdecoder_illegal_tb top;

  const DecodeCase cases[] = {
      {"valid_ctz", 0x60101013u, false, 0u},
      {"invalid_ctz_reserved_bits", 0x60901013u, true, 2u},
  };

  bool all_ok = true;
  for (const auto& test_case : cases) {
    top.instruction_i = test_case.instruction;
    top.eval();

    const bool got_exception = top.exception_valid_o != 0;
    bool ok = got_exception == test_case.expect_exception;
    if (test_case.expect_exception) {
      ok = ok && (top.exception_cause_o == test_case.expect_cause) &&
           (top.exception_tval_o == test_case.instruction);
    } else {
      ok = ok && (top.exception_cause_o == 0u);
    }

    std::cout << test_case.name << ": instr=0x" << std::hex << test_case.instruction
              << " exception=" << std::dec << static_cast<int>(got_exception)
              << " cause=" << top.exception_cause_o
              << " tval=0x" << std::hex << top.exception_tval_o << std::dec
              << (ok ? " OK" : " BAD") << std::endl;
    all_ok = all_ok && ok;
  }

  top.final();
  return all_ok ? 0 : 1;
}
