    csr_write_fflags_i = 1'b0;
    dirty_v_state_i = 1'b0;
    pc_i = '0;
    acc_fflags_ex_i = '0;
    acc_fflags_ex_valid_i = 1'b0;
    csr_hs_ld_st_inst_i = 1'b0;
    irq_i = '0;
    ipi_i = 1'b0;
    debug_req_i = 1'b0;
    perf_data_i = '0;

    repeat (4) @(posedge clk_i);
    rst_ni = 1'b1;
    repeat (2) @(posedge clk_i);

    csr_addr_i = riscv::CSR_PMPCFG1;
    csr_wdata_i = PMPCFG1_PATTERN;
    csr_op_i = ariane_pkg::CSR_WRITE;
    @(posedge clk_i);

    csr_op_i = ariane_pkg::ADD;
    csr_wdata_i = '0;
    @(posedge clk_i);

    csr_op_i = ariane_pkg::CSR_READ;
    #1;

    $display("PMPCFG1 csr_rdata_o = 0x%08x", csr_rdata_o);
    $display("PMPCFG1 pmpcfg_o[7:4] = 0x%08x", observed_pmpcfg1);
    if (observed_pmpcfg1 !== PMPCFG1_PATTERN) begin
      $fatal(1,
             "PMPCFG1 output mismatch: expected 0x%08x, got 0x%08x",
             PMPCFG1_PATTERN,
             observed_pmpcfg1);
    end

    $display("PMPCFG1 output matched expected value.");
    $finish;
  end
endmodule
EOF

