  ariane_pkg::frontend_exception_t exception_i;
  logic [CFG.VLEN-1:0] exception_addr_i;
  logic [CFG.GPLEN-1:0] exception_gpaddr_i;
  logic [31:0] exception_tinst_i;
  logic exception_gva_i;
  logic [CFG.VLEN-1:0] predict_address_i;
  ariane_pkg::cf_t [CFG.INSTR_PER_FETCH-1:0] cf_type_i;
  logic replay_o;
  logic [CFG.VLEN-1:0] replay_addr_o;
  fetch_entry_t [CFG.NrIssuePorts-1:0] fetch_entry_o;
  logic [CFG.NrIssuePorts-1:0] fetch_entry_valid_o;
  logic [CFG.NrIssuePorts-1:0] fetch_entry_ready_i;

  instr_queue #(
      .CVA6Cfg(CFG),
      .fetch_entry_t(fetch_entry_t)
  ) dut (
      .clk_i,
      .rst_ni,
      .flush_i,
      .instr_i,
      .addr_i,
      .valid_i,
      .ready_o,
      .consumed_o,
      .exception_i,
      .exception_addr_i,
      .exception_gpaddr_i,
      .exception_tinst_i,
      .exception_gva_i,
      .predict_address_i,
      .cf_type_i,
      .replay_o,
      .replay_addr_o,
      .fetch_entry_o,
      .fetch_entry_valid_o,
      .fetch_entry_ready_i
  );

  always #1 clk_i = ~clk_i;

  task automatic drive_branch_packet(input logic [CFG.VLEN-1:0] base_addr,
                                     input logic [CFG.VLEN-1:0] target_addr);
    begin
      instr_i = '0;
      addr_i = '0;
      valid_i = '0;
      cf_type_i = '{default: ariane_pkg::NoCF};
      instr_i[0] = 32'h0000_0063;
      addr_i[0] = base_addr;
      addr_i[1] = base_addr + 32'd2;
      addr_i[2] = base_addr + 32'd4;
      addr_i[3] = base_addr + 32'd6;
      valid_i[0] = 1'b1;
      cf_type_i[0] = ariane_pkg::Branch;
      predict_address_i = target_addr;
    end
  endtask

  initial begin
    clk_i = 1'b0;
    rst_ni = 1'b0;
    flush_i = 1'b0;
    instr_i = '0;
    addr_i = '0;
    valid_i = '0;
    exception_i = ariane_pkg::FE_NONE;
    exception_addr_i = '0;
    exception_gpaddr_i = '0;
    exception_tinst_i = '0;
    exception_gva_i = 1'b0;
    predict_address_i = '0;
    cf_type_i = '{default: ariane_pkg::NoCF};
    fetch_entry_ready_i = '0;

    repeat (2) @(negedge clk_i);
    rst_ni = 1'b1;

    drive_branch_packet(32'h1000, 32'h2000);
    @(negedge clk_i);
    if (ready_o !== 1'b1 || replay_o !== 1'b0) begin
      $fatal(1, "unexpected state after first predicted branch packet");
    end

    drive_branch_packet(32'h1002, 32'h2002);
    @(negedge clk_i);
    if (ready_o !== 1'b0) begin
      $fatal(1, "expected address queue backpressure after two outstanding predicted branches");
    end

    drive_branch_packet(32'h1004, 32'h2004);
    @(negedge clk_i);
    if (ready_o !== 1'b0 || replay_o !== 1'b1 || replay_addr_o !== 32'h00001004) begin
      $fatal(1, "expected replay on the third predicted branch packet");
    end

    $display("TB PASS");
    $finish;
  end
endmodule
EOF

