  >"$BUILD_LOG" 2>&1
rc=$?

if [[ $rc -eq 0 ]]; then
  "$TB_DIR/obj_dir/Vtb_cva6_rvfi" >"$RUN_LOG" 2>&1
  rc=$?
fi
set -e

if [[ $rc -ne 0 ]]; then
  if [[ -s "$RUN_LOG" ]]; then
    echo "[rvfi-test] simulation failed; excerpt from $RUN_LOG:"
    tail -n 40 "$RUN_LOG"
  elif [[ -s "$BUILD_LOG" ]]; then
