#include "Vlsu_pmp_tb.h"
#include "verilated.h"

#include <cstdint>
#include <iostream>

static void tick(Vlsu_pmp_tb* top, std::uint64_t& time_value) {
  top->clk_i = 0;
  top->eval();
  ++time_value;

  top->clk_i = 1;
  top->eval();
  ++time_value;
}

int main(int argc, char** argv) {
  Verilated::commandArgs(argc, argv);
  Vlsu_pmp_tb top;
  std::uint64_t time_value = 0;

  top.clk_i = 0;
  top.rst_ni = 0;
  top.eval();

  tick(&top, time_value);
  tick(&top, time_value);

  top.rst_ni = 1;

  for (int cycle = 0; cycle < 80; ++cycle) {
    tick(&top, time_value);
    if (top.done_o) {
      std::cout << "TB_STATUS " << std::hex << top.status_code_o << std::dec << std::endl;
      top.final();
      return top.pass_o ? 0 : 1;
    }
  }

  std::cout << "TB_STATUS timeout_from_cpp" << std::endl;
  top.final();
  return 1;
}
EOF

