fi

cat > "$TB_DIR/tb_bht_wrapper.sv" <<'EOF'
module tb_bht_wrapper (
    input logic clk_i,
    input logic rst_ni,
    input logic flush_bp_i,
    input logic debug_mode_i,
    input logic [31:0] vpc_i,
    input logic update_valid_i,
    input logic [31:0] update_pc_i,
    input logic update_taken_i,
    output logic lane0_valid_o,
    output logic lane0_taken_o,
    output logic lane1_valid_o,
    output logic lane1_taken_o
);

  function automatic config_pkg::cva6_cfg_t make_tb_cfg();
    config_pkg::cva6_cfg_t cfg;
    cfg = build_config_pkg::build_config(cva6_config_pkg::cva6_cfg);
    cfg.FpgaEn = 1'b1;
    return cfg;
  endfunction

  localparam config_pkg::cva6_cfg_t TB_CFG = make_tb_cfg();

  typedef struct packed {
    logic valid;
    logic [TB_CFG.VLEN-1:0] pc;
    logic taken;
  } bht_update_t;

  bht_update_t bht_update;
  ariane_pkg::bht_prediction_t [TB_CFG.INSTR_PER_FETCH-1:0] bht_prediction;

  assign bht_update.valid = update_valid_i;
  assign bht_update.pc = update_pc_i;
  assign bht_update.taken = update_taken_i;

  bht #(
      .CVA6Cfg(TB_CFG),
      .bht_update_t(bht_update_t),
      .NR_ENTRIES(TB_CFG.BHTEntries)
  ) i_bht (
      .clk_i(clk_i),
      .rst_ni(rst_ni),
      .flush_bp_i(flush_bp_i),
      .debug_mode_i(debug_mode_i),
      .vpc_i(vpc_i),
      .bht_update_i(bht_update),
      .bht_prediction_o(bht_prediction)
  );

  assign lane0_valid_o = bht_prediction[0].valid;
  assign lane0_taken_o = bht_prediction[0].taken;
  assign lane1_valid_o = bht_prediction[1].valid;
  assign lane1_taken_o = bht_prediction[1].taken;

endmodule
EOF

cat > "$TB_DIR/tb_bht_main.cpp" <<'EOF'
#include "Vtb_bht_wrapper.h"
#include "verilated.h"

#include <cstdint>
#include <iostream>
#include <string>

namespace {

void tick(Vtb_bht_wrapper* top) {
  top->clk_i = 0;
  top->eval();
  top->clk_i = 1;
  top->eval();
}

void drive_idle(Vtb_bht_wrapper* top) {
  top->flush_bp_i = 0;
  top->debug_mode_i = 0;
  top->update_valid_i = 0;
  top->update_pc_i = 0;
  top->update_taken_i = 0;
}

void reset_dut(Vtb_bht_wrapper* top) {
  drive_idle(top);
  top->vpc_i = 0;
  top->rst_ni = 0;
  tick(top);
  tick(top);
  top->rst_ni = 1;
  top->eval();
}

void train_taken(Vtb_bht_wrapper* top, uint32_t pc, int repetitions) {
  for (int i = 0; i < repetitions; ++i) {
    drive_idle(top);
    top->vpc_i = 0;
    top->update_valid_i = 1;
    top->update_pc_i = pc;
    top->update_taken_i = 1;
    top->eval();
    tick(top);
    drive_idle(top);
    top->eval();
  }
}

bool expect_lane(Vtb_bht_wrapper* top, uint32_t vpc, bool lane1, bool exp_valid,
                 bool exp_taken, const char* label) {
  drive_idle(top);
  top->vpc_i = vpc;
  top->eval();

  const bool got_valid = lane1 ? top->lane1_valid_o : top->lane0_valid_o;
  const bool got_taken = lane1 ? top->lane1_taken_o : top->lane0_taken_o;
  if (got_valid != exp_valid || got_taken != exp_taken) {
    std::cerr << label << " expected valid=" << exp_valid << " taken=" << exp_taken
              << " but got valid=" << got_valid << " taken=" << got_taken << '\n';
    return false;
  }
  return true;
}

}  // namespace

int main(int argc, char** argv) {
  Verilated::commandArgs(argc, argv);
  auto* top = new Vtb_bht_wrapper;

  reset_dut(top);

  // Train BHT row 1 / lane 1 to strongly-taken so that lane 1 has a known
  // non-zero prediction before switching to a row_index==0 lookup.
  train_taken(top, 0x6, 2);

  bool ok = true;
  ok &= expect_lane(top, 0x6, true, true, true, "row1_lane1_after_training");
  ok &= expect_lane(top, 0x0, false, false, false, "row0_lane0_default");
  ok &= expect_lane(top, 0x0, true, false, false, "row0_lane1_must_refresh");

  top->final();
  delete top;
  return ok ? 0 : 1;
}
EOF

