#!/bin/bash
set -uo pipefail

cd /home/cva6

TB_NAME="pmpcfg0_napot_warl_cv32a65x"
TB_DIR="/home/cva6/.tb_pmpcfg0_napot_warl"
OBJ_DIR="$TB_DIR/obj_dir"
LOG_FILE="$TB_DIR/verilator_run.log"
