ln -s /tools/verilator/share/verilator/include "$VERI_ROOT/include"

cat > "$TB_DIR/${TB_NAME}.sv" <<'EOF'
`include "rvfi_types.svh"

module pmpcfg0_napot_warl_cv32a65x_tb;
  import riscv::*;
  import config_pkg::*;
  import cva6_config_pkg::*;
  import ariane_pkg::*;

  localparam cva6_cfg_t CVA6Cfg = build_config_pkg::build_config(cva6_cfg);
  localparam logic [11:0] TB_PMPCFG0_ADDR = 12'h3A0;
  localparam logic [CVA6Cfg.XLEN-1:0] PMP_TOR_RWX = 32'h0000_000F;
  localparam logic [CVA6Cfg.XLEN-1:0] PMP_NAPOT_RWX = 32'h0000_001F;

  typedef struct packed {
    logic [CVA6Cfg.VLEN-1:0] predict_address;
  } branchpredict_sbe_t;

  typedef struct packed {
    logic [CVA6Cfg.XLEN-1:0] cause;
    logic [CVA6Cfg.XLEN-1:0] tval;
    logic [CVA6Cfg.GPLEN-1:0] tval2;
    logic [31:0] tinst;
    logic gva;
    logic valid;
  } exception_t;

  typedef struct packed {
    logic [CVA6Cfg.VLEN-1:0] pc;
    fu_t fu;
    branchpredict_sbe_t bp;
    logic is_compressed;
  } scoreboard_entry_t;

  typedef struct packed {
    logic [CVA6Cfg.XLEN-1:0] mie;
    logic [CVA6Cfg.XLEN-1:0] mip;
    logic [CVA6Cfg.XLEN-1:0] mideleg;
    logic [CVA6Cfg.XLEN-1:0] hideleg;
    logic sie;
    logic global_enable;
  } irq_ctrl_t;

  typedef `RVFI_PROBES_CSR_T(CVA6Cfg) rvfi_probes_csr_t;

  logic clk_i;
  logic rst_ni;
  logic time_irq_i;
  logic flush_o;
  logic halt_csr_o;
  scoreboard_entry_t commit_instr_i;
  logic [CVA6Cfg.NrCommitPorts-1:0] commit_ack_i;
  logic [CVA6Cfg.VLEN-1:0] boot_addr_i;
  logic [CVA6Cfg.XLEN-1:0] hart_id_i;
  exception_t ex_i;
  fu_op csr_op_i;
  logic [11:0] csr_addr_i;
  logic [CVA6Cfg.XLEN-1:0] csr_wdata_i;
  logic [CVA6Cfg.XLEN-1:0] csr_rdata_o;
  logic dirty_fp_state_i;
  logic csr_write_fflags_i;
  logic dirty_v_state_i;
  logic [CVA6Cfg.VLEN-1:0] pc_i;
  exception_t csr_exception_o;
  logic [CVA6Cfg.VLEN-1:0] epc_o;
  logic eret_o;
  logic [CVA6Cfg.VLEN-1:0] trap_vector_base_o;
  riscv::priv_lvl_t priv_lvl_o;
  logic v_o;
  logic [4:0] acc_fflags_ex_i;
  logic acc_fflags_ex_valid_i;
  riscv::xs_t fs_o;
  riscv::xs_t vfs_o;
  logic [4:0] fflags_o;
  logic [2:0] frm_o;
  logic [6:0] fprec_o;
  riscv::xs_t vs_o;
  irq_ctrl_t irq_ctrl_o;
  logic en_translation_o;
  logic en_g_translation_o;
  logic en_ld_st_translation_o;
  logic en_ld_st_g_translation_o;
  riscv::priv_lvl_t ld_st_priv_lvl_o;
  logic ld_st_v_o;
  logic csr_hs_ld_st_inst_i;
  logic sum_o;
  logic vs_sum_o;
  logic mxr_o;
  logic vmxr_o;
  logic [CVA6Cfg.PPNW-1:0] satp_ppn_o;
  logic [CVA6Cfg.ASID_WIDTH-1:0] asid_o;
  logic [CVA6Cfg.PPNW-1:0] vsatp_ppn_o;
  logic [CVA6Cfg.ASID_WIDTH-1:0] vs_asid_o;
  logic [CVA6Cfg.PPNW-1:0] hgatp_ppn_o;
  logic [CVA6Cfg.VMID_WIDTH-1:0] vmid_o;
  logic [1:0] irq_i;
  logic ipi_i;
  logic debug_req_i;
  logic set_debug_pc_o;
  logic tvm_o;
  logic tw_o;
  logic vtw_o;
  logic tsr_o;
  logic hu_o;
  logic debug_mode_o;
  logic single_step_o;
  logic icache_en_o;
  logic dcache_en_o;
  logic acc_cons_en_o;
  logic [11:0] perf_addr_o;
  logic [CVA6Cfg.XLEN-1:0] perf_data_o;
  logic [CVA6Cfg.XLEN-1:0] perf_data_i;
  logic perf_we_o;
  riscv::pmpcfg_t [(CVA6Cfg.NrPMPEntries > 0 ? CVA6Cfg.NrPMPEntries-1 : 0):0] pmpcfg_o;
  logic [(CVA6Cfg.NrPMPEntries > 0 ? CVA6Cfg.NrPMPEntries-1 : 0):0][CVA6Cfg.PLEN-3:0] pmpaddr_o;
  logic [31:0] mcountinhibit_o;
  rvfi_probes_csr_t rvfi_csr_o;

  csr_regfile #(
    .CVA6Cfg(CVA6Cfg),
    .exception_t(exception_t),
    .irq_ctrl_t(irq_ctrl_t),
    .scoreboard_entry_t(scoreboard_entry_t),
    .rvfi_probes_csr_t(rvfi_probes_csr_t)
  ) dut (
    .clk_i,
    .rst_ni,
    .time_irq_i,
    .flush_o,
    .halt_csr_o,
    .commit_instr_i,
    .commit_ack_i,
    .boot_addr_i,
    .hart_id_i,
    .ex_i,
    .csr_op_i,
    .csr_addr_i,
    .csr_wdata_i,
    .csr_rdata_o,
    .dirty_fp_state_i,
    .csr_write_fflags_i,
    .dirty_v_state_i,
    .pc_i,
    .csr_exception_o,
    .epc_o,
    .eret_o,
    .trap_vector_base_o,
    .priv_lvl_o,
    .v_o,
    .acc_fflags_ex_i,
    .acc_fflags_ex_valid_i,
    .fs_o,
    .vfs_o,
    .fflags_o,
    .frm_o,
    .fprec_o,
    .vs_o,
    .irq_ctrl_o,
    .en_translation_o,
    .en_g_translation_o,
    .en_ld_st_translation_o,
    .en_ld_st_g_translation_o,
    .ld_st_priv_lvl_o,
    .ld_st_v_o,
    .csr_hs_ld_st_inst_i,
    .sum_o,
    .vs_sum_o,
    .mxr_o,
    .vmxr_o,
    .satp_ppn_o,
    .asid_o,
    .vsatp_ppn_o,
    .vs_asid_o,
    .hgatp_ppn_o,
    .vmid_o,
    .irq_i,
    .ipi_i,
    .debug_req_i,
    .set_debug_pc_o,
    .tvm_o,
    .tw_o,
    .vtw_o,
    .tsr_o,
    .hu_o,
    .debug_mode_o,
    .single_step_o,
    .icache_en_o,
    .dcache_en_o,
    .acc_cons_en_o,
    .perf_addr_o,
    .perf_data_o,
    .perf_data_i,
    .perf_we_o,
    .pmpcfg_o,
    .pmpaddr_o,
    .mcountinhibit_o,
    .rvfi_csr_o
  );

  always #5 clk_i = ~clk_i;

  task automatic set_idle_inputs;
    begin
      time_irq_i = 1'b0;
      commit_instr_i = '0;
      commit_instr_i.fu = NONE;
      commit_ack_i = '0;
      boot_addr_i = '0;
      hart_id_i = '0;
      ex_i = '0;
      csr_op_i = ADD;
      csr_addr_i = '0;
      csr_wdata_i = '0;
      dirty_fp_state_i = 1'b0;
      csr_write_fflags_i = 1'b0;
      dirty_v_state_i = 1'b0;
      pc_i = '0;
      acc_fflags_ex_i = '0;
      acc_fflags_ex_valid_i = 1'b0;
      csr_hs_ld_st_inst_i = 1'b0;
      irq_i = '0;
      ipi_i = 1'b0;
      debug_req_i = 1'b0;
      perf_data_i = '0;
    end
  endtask

  task automatic csr_write(input logic [11:0] addr, input logic [CVA6Cfg.XLEN-1:0] data);
    begin
      @(negedge clk_i);
      csr_addr_i = addr;
      csr_wdata_i = data;
      csr_op_i = CSR_WRITE;
      @(posedge clk_i);
      #1;
      csr_op_i = ADD;
      csr_addr_i = '0;
      csr_wdata_i = '0;
    end
  endtask

  task automatic expect_read(input logic [11:0] addr, input logic [CVA6Cfg.XLEN-1:0] expected, input string msg);
    logic [CVA6Cfg.XLEN-1:0] observed;
    begin
      @(negedge clk_i);
      csr_addr_i = addr;
      csr_op_i = CSR_READ;
      #1;
      observed = csr_rdata_o;
      if (observed !== expected) begin
        $display("Mismatch: %s expected=0x%08x observed=0x%08x", msg, expected, observed);
        $fatal(1);
      end
      @(posedge clk_i);
      #1;
      csr_op_i = ADD;
      csr_addr_i = '0;
    end
  endtask

  initial begin
    clk_i = 1'b0;
    rst_ni = 1'b0;
    set_idle_inputs();

    repeat (4) @(posedge clk_i);
    rst_ni = 1'b1;
    repeat (2) @(posedge clk_i);

    expect_read(TB_PMPCFG0_ADDR, 32'h0000_0000, "reset state");
    csr_write(TB_PMPCFG0_ADDR, PMP_TOR_RWX);
    expect_read(TB_PMPCFG0_ADDR, PMP_TOR_RWX, "TOR write must stick");
    csr_write(TB_PMPCFG0_ADDR, PMP_NAPOT_RWX);
    expect_read(TB_PMPCFG0_ADDR, PMP_TOR_RWX, "NAPOT write must be WARL-nochange on cv32a65x");

    $display("Observed WARL behavior matches expectation.");
    $finish(0);
  end
endmodule
EOF

