    logic                         is_last_macro_instr;
    logic                         is_double_rd_macro_instr;
    logic                         vfp;
  } scoreboard_entry_t;

  typedef struct packed {
    logic [CFG.XLEN-1:0] mie;
    logic [CFG.XLEN-1:0] mip;
    logic [CFG.XLEN-1:0] mideleg;
    logic [CFG.XLEN-1:0] hideleg;
    logic                sie;
    logic                global_enable;
  } irq_ctrl_t;

  typedef `RVFI_PROBES_CSR_T(CFG) rvfi_probes_csr_t;

  logic clk_i;
  logic rst_ni;
  logic time_irq_i;
  logic flush_o;
  logic halt_csr_o;
  scoreboard_entry_t commit_instr_i;
  logic [CFG.NrCommitPorts-1:0] commit_ack_i;
  logic [CFG.VLEN-1:0] boot_addr_i;
  logic [CFG.XLEN-1:0] hart_id_i;
  exception_t ex_i;
  fu_op csr_op_i;
  logic [11:0] csr_addr_i;
  logic [CFG.XLEN-1:0] csr_wdata_i;
  logic [CFG.XLEN-1:0] csr_rdata_o;
  logic dirty_fp_state_i;
  logic csr_write_fflags_i;
  logic dirty_v_state_i;
  logic [CFG.VLEN-1:0] pc_i;
  exception_t csr_exception_o;
  logic [CFG.VLEN-1:0] epc_o;
  logic eret_o;
  logic [CFG.VLEN-1:0] trap_vector_base_o;
  riscv::priv_lvl_t priv_lvl_o;
  logic v_o;
  logic [4:0] acc_fflags_ex_i;
  logic acc_fflags_ex_valid_i;
  riscv::xs_t fs_o;
  riscv::xs_t vfs_o;
  logic [4:0] fflags_o;
  logic [2:0] frm_o;
  logic [6:0] fprec_o;
  riscv::xs_t vs_o;
  irq_ctrl_t irq_ctrl_o;
  logic en_translation_o;
  logic en_g_translation_o;
  logic en_ld_st_translation_o;
  logic en_ld_st_g_translation_o;
  riscv::priv_lvl_t ld_st_priv_lvl_o;
  logic ld_st_v_o;
  logic csr_hs_ld_st_inst_i;
  logic sum_o;
  logic vs_sum_o;
  logic mxr_o;
  logic vmxr_o;
  logic [CFG.PPNW-1:0] satp_ppn_o;
  logic [CFG.ASID_WIDTH-1:0] asid_o;
  logic [CFG.PPNW-1:0] vsatp_ppn_o;
  logic [CFG.ASID_WIDTH-1:0] vs_asid_o;
  logic [CFG.PPNW-1:0] hgatp_ppn_o;
  logic [CFG.VMID_WIDTH-1:0] vmid_o;
  logic [1:0] irq_i;
  logic ipi_i;
  logic debug_req_i;
  logic set_debug_pc_o;
  logic tvm_o;
  logic tw_o;
  logic vtw_o;
  logic tsr_o;
  logic hu_o;
  logic debug_mode_o;
