    .irq_ctrl_t(irq_ctrl_t),
    .scoreboard_entry_t(scoreboard_entry_t),
    .rvfi_probes_csr_t(rvfi_probes_csr_t)
  ) dut (
    .clk_i(clk_i),
    .rst_ni(rst_ni),
    .time_irq_i(time_irq_i),
    .flush_o(flush_o),
    .halt_csr_o(halt_csr_o),
    .commit_instr_i(commit_instr_i),
    .commit_ack_i(commit_ack_i),
    .boot_addr_i(boot_addr_i),
    .hart_id_i(hart_id_i),
    .ex_i(ex_i),
    .csr_op_i(csr_op_i),
    .csr_addr_i(csr_addr_i),
    .csr_wdata_i(csr_wdata_i),
    .csr_rdata_o(csr_rdata_o),
    .dirty_fp_state_i(dirty_fp_state_i),
    .csr_write_fflags_i(csr_write_fflags_i),
    .dirty_v_state_i(dirty_v_state_i),
    .pc_i(pc_i),
    .csr_exception_o(csr_exception_o),
    .epc_o(epc_o),
    .eret_o(eret_o),
    .trap_vector_base_o(trap_vector_base_o),
    .priv_lvl_o(priv_lvl_o),
    .v_o(v_o),
    .acc_fflags_ex_i(acc_fflags_ex_i),
    .acc_fflags_ex_valid_i(acc_fflags_ex_valid_i),
    .fs_o(fs_o),
    .vfs_o(vfs_o),
    .fflags_o(fflags_o),
    .frm_o(frm_o),
    .fprec_o(fprec_o),
    .vs_o(vs_o),
    .irq_ctrl_o(irq_ctrl_o),
    .en_translation_o(en_translation_o),
    .en_g_translation_o(en_g_translation_o),
    .en_ld_st_translation_o(en_ld_st_translation_o),
    .en_ld_st_g_translation_o(en_ld_st_g_translation_o),
    .ld_st_priv_lvl_o(ld_st_priv_lvl_o),
    .ld_st_v_o(ld_st_v_o),
    .csr_hs_ld_st_inst_i(csr_hs_ld_st_inst_i),
    .sum_o(sum_o),
    .vs_sum_o(vs_sum_o),
    .mxr_o(mxr_o),
    .vmxr_o(vmxr_o),
    .satp_ppn_o(satp_ppn_o),
    .asid_o(asid_o),
    .vsatp_ppn_o(vsatp_ppn_o),
    .vs_asid_o(vs_asid_o),
    .hgatp_ppn_o(hgatp_ppn_o),
    .vmid_o(vmid_o),
    .irq_i(irq_i),
    .ipi_i(ipi_i),
    .debug_req_i(debug_req_i),
    .set_debug_pc_o(set_debug_pc_o),
    .tvm_o(tvm_o),
    .tw_o(tw_o),
    .vtw_o(vtw_o),
    .tsr_o(tsr_o),
    .hu_o(hu_o),
    .debug_mode_o(debug_mode_o),
    .single_step_o(single_step_o),
    .icache_en_o(icache_en_o),
    .dcache_en_o(dcache_en_o),
    .acc_cons_en_o(acc_cons_en_o),
    .perf_addr_o(perf_addr_o),
    .perf_data_o(perf_data_o),
    .perf_data_i(perf_data_i),
    .perf_we_o(perf_we_o),
    .pmpcfg_o(pmpcfg_o),
    .pmpaddr_o(pmpaddr_o),
    .mcountinhibit_o(mcountinhibit_o),
    .rvfi_csr_o(rvfi_csr_o)
  );

  always #5 clk_i = ~clk_i;

  task automatic clear_csr_op;
    begin
      @(negedge clk_i);
      csr_op_i <= ADD;
      csr_addr_i <= '0;
      csr_wdata_i <= '0;
    end
  endtask

  task automatic csr_write(input logic [11:0] addr, input logic [CFG.XLEN-1:0] data);
    begin
      @(negedge clk_i);
      csr_addr_i = addr;
      csr_wdata_i = data;
      csr_op_i = CSR_WRITE;
      @(posedge clk_i);
      #1;
      if (csr_exception_o.valid) begin
        $display("unexpected csr write exception at addr=0x%0h", addr);
        $fatal(1);
      end
      clear_csr_op();
    end
  endtask

  task automatic csr_read_expect_bit3_zero(input logic [11:0] addr, input string name);
    logic [CFG.XLEN-1:0] value;
    begin
      @(negedge clk_i);
      csr_addr_i = addr;
      csr_wdata_i = '0;
      csr_op_i = CSR_READ;
      @(posedge clk_i);
      #1;
      value = csr_rdata_o;
      if (csr_exception_o.valid) begin
        $display("unexpected csr read exception at addr=0x%0h", addr);
        $fatal(1);
      end
      $display("%s = 0x%08x", name, value);
      if (value[3] !== 1'b0) begin
        $display("%s bit3 should stay zero", name);
        $fatal(1);
      end
      clear_csr_op();
    end
  endtask

  initial begin
    clk_i = 1'b0;
    rst_ni = 1'b0;
    time_irq_i = 1'b0;
    commit_instr_i = '0;
    commit_ack_i = '0;
    boot_addr_i = 32'h8000_0000;
    hart_id_i = '0;
    ex_i = '0;
    csr_op_i = ADD;
    csr_addr_i = '0;
    csr_wdata_i = '0;
    dirty_fp_state_i = 1'b0;
    csr_write_fflags_i = 1'b0;
    dirty_v_state_i = 1'b0;
    pc_i = '0;
    acc_fflags_ex_i = '0;
    acc_fflags_ex_valid_i = 1'b0;
    csr_hs_ld_st_inst_i = 1'b0;
    irq_i = '0;
    ipi_i = 1'b0;
    debug_req_i = 1'b0;
    perf_data_i = '0;

    repeat (3) @(posedge clk_i);
    rst_ni = 1'b1;
    repeat (2) @(posedge clk_i);
    #1;

    if (CFG.RVS !== 1'b0 || CFG.RVU !== 1'b0) begin
      $display("unexpected config: this test requires M-mode only");
      $fatal(1);
    end

    csr_write(riscv::CSR_MIE, 32'h0000_0008);
    csr_read_expect_bit3_zero(riscv::CSR_MIE, "mie");

    @(negedge clk_i);
    ipi_i = 1'b1;
    @(posedge clk_i);
    #1;
    csr_read_expect_bit3_zero(riscv::CSR_MIP, "mip");

    $display("software interrupt bits are read-only zero as expected");
    $finish;
  end
endmodule
EOF

python3 - <<'PY' > "$BUILD_LOG" 2>&1
from pathlib import Path
import re

src = Path("/home/cva6/core/include/config_pkg.sv").read_text()
replacement = """  function automatic void check_cfg(cva6_cfg_t Cfg);
    // pragma translate_off
    assert (Cfg.RASDepth > 0);
    assert (Cfg.BTBEntries == 0 || (2 ** $clog2(Cfg.BTBEntries) == Cfg.BTBEntries));
    assert (Cfg.BHTEntries == 0 || (2 ** $clog2(Cfg.BHTEntries) == Cfg.BHTEntries));
    assert (Cfg.NrNonIdempotentRules <= NrMaxRules);
    assert (Cfg.NrExecuteRegionRules <= NrMaxRules);
    assert (Cfg.NrCachedRegionRules <= NrMaxRules);
    assert (Cfg.NrPMPEntries <= 64);
    assert (!(Cfg.SuperscalarEn && Cfg.RVF));
    assert (!(Cfg.SuperscalarEn && Cfg.RVZCMP));
    assert (Cfg.FETCH_WIDTH == 32 || Cfg.FETCH_WIDTH == 64)
      else $fatal(1, "[frontend] fetch width != not supported");
    // pragma translate_on
  endfunction
"""
out, count = re.subn(
    r"  function automatic void check_cfg\(cva6_cfg_t Cfg\);.*?  endfunction\n",
    replacement,
    src,
    count=1,
    flags=re.S,
)
if count != 1:
    raise SystemExit("failed to rewrite check_cfg in config_pkg.sv")
Path("/home/cva6/.tb_csr_sw_interrupt_readonly/config_pkg_local.sv").write_text(out)
PY
prep_rc=$?

build_rc=$prep_rc
run_rc=1
final_rc=1
status=FAIL

if [ "$prep_rc" -eq 0 ]; then
  unset VERILATOR_BIN
  unset VERILATOR_ROOT
  timeout 1200 /tools/verilator/bin/verilator \
    --binary \
    --timing \
    --timescale 1ns/1ps \
    --top-module tb_csr_sw_interrupt_readonly \
    --Mdir "$OBJ_DIR" \
    -Wno-fatal \
    -Wno-INITIALDLY \
    -Wno-LATCH \
    -Wno-TIMESCALEMOD \
    -Wno-UNSIGNED \
    -Wno-WIDTHEXPAND \
    -Wno-WIDTHTRUNC \
    -I/home/cva6/core/include \
    -I/home/cva6/vendor/pulp-platform/axi/src \
    "$TB_DIR/config_pkg_local.sv" \
    /home/cva6/core/include/cv32a65x_config_pkg.sv \
    /home/cva6/core/include/riscv_pkg.sv \
    /home/cva6/core/include/ariane_pkg.sv \
    /home/cva6/vendor/pulp-platform/axi/src/axi_pkg.sv \
    /home/cva6/core/include/wt_cache_pkg.sv \
    /home/cva6/core/include/std_cache_pkg.sv \
    /home/cva6/core/include/build_config_pkg.sv \
    /home/cva6/core/csr_regfile.sv \
    "$TB_DIR/tb.sv" \
    >>"$BUILD_LOG" 2>&1
  build_rc=$?
fi

if [ "$build_rc" -eq 0 ]; then
  timeout 1200 "$TOP_BIN" >"$RUN_LOG" 2>&1
  run_rc=$?
else
  run_rc=$build_rc
fi

if [ "$build_rc" -eq 124 ] || [ "$run_rc" -eq 124 ]; then
  final_rc=124
elif [ "$build_rc" -eq 0 ] && [ "$run_rc" -eq 0 ]; then
  final_rc=0
  status=PASS
else
  final_rc=1
fi

if [ "$build_rc" -ne 0 ]; then
  echo "[tb] build failed with rc=$build_rc"
  tail -n 80 "$BUILD_LOG"
elif [ "$run_rc" -ne 0 ]; then
  echo "[tb] simulation failed with rc=$run_rc"
  tail -n 80 "$RUN_LOG"
else
  echo "[tb] simulation completed successfully"
  tail -n 40 "$RUN_LOG"
fi

echo "HWE_BENCH_RESULTS_START"
echo "TEST: $TEST_NAME ... $status"
echo "HWE_BENCH_RESULTS_END"

exit "$final_rc"

resolved_issues.body:
### Is there an existing CVA6 bug for this?

- [X] I have searched the existing bug issues

### Bug Description

According to RISC-V ISA specification, for RV32, the bit 25 of instructions `BCLRI`, `BINVI`, `BSETI`, `BEXTI` and `RORI` must be equal to zero.
So when this bit is set, an illegal instruction exception has to be raised.

With the current implementation, when bit 25 is set, there is no exception for RV32.

```
end else if (instr.instr[31:26] == 6'b010010) instruction_o.op = ariane_pkg::BCLRI;
                else if (instr.instr[31:26] == 6'b011010) instruction_o.op = ariane_pkg::BINVI;
                else if (instr.instr[31:26] == 6'b001010) instruction_o.op = ariane_pkg::BSETI;
                else illegal_instr_bm = 1'b1;
```

```
  else if (instr.instr[31:26] == 6'b010_010) instruction_o.op = ariane_pkg::BEXTI;
                else if (instr.instr[31:26] == 6'b011_000) instruction_o.op = ariane_pkg::RORI;
                else illegal_instr_bm = 1'b1;           
```

fix_patch:
diff --git a/core/decoder.sv b/core/decoder.sv
index 2d137648f0..169c9b6283 100644
--- a/core/decoder.sv
+++ b/core/decoder.sv
@@ -916,9 +916,18 @@ module decoder
                   else if (instr.instr[24:20] == 5'b00000) instruction_o.op = ariane_pkg::CLZ;
                   else if (instr.instr[24:20] == 5'b00001) instruction_o.op = ariane_pkg::CTZ;
                   else illegal_instr_bm = 1'b1;
-                end else if (instr.instr[31:26] == 6'b010010) instruction_o.op = ariane_pkg::BCLRI;
-                else if (instr.instr[31:26] == 6'b011010) instruction_o.op = ariane_pkg::BINVI;
-                else if (instr.instr[31:26] == 6'b001010) instruction_o.op = ariane_pkg::BSETI;
+                end else if (CVA6Cfg.IS_XLEN64 && instr.instr[31:26] == 6'b010010)
+                  instruction_o.op = ariane_pkg::BCLRI;
+                else if (CVA6Cfg.IS_XLEN32 && instr.instr[31:25] == 7'b0100100)
+                  instruction_o.op = ariane_pkg::BCLRI;
+                else if (CVA6Cfg.IS_XLEN64 && instr.instr[31:26] == 6'b011010)
+                  instruction_o.op = ariane_pkg::BINVI;
+                else if (CVA6Cfg.IS_XLEN32 && instr.instr[31:25] == 7'b0110100)
+                  instruction_o.op = ariane_pkg::BINVI;
+                else if (CVA6Cfg.IS_XLEN64 && instr.instr[31:26] == 6'b001010)
+                  instruction_o.op = ariane_pkg::BSETI;
+                else if (CVA6Cfg.IS_XLEN32 && instr.instr[31:25] == 7'b0010100)
+                  instruction_o.op = ariane_pkg::BSETI;
                 else if (CVA6Cfg.ZKN && instr.instr[31:20] == 12'b000010001111)
                   instruction_o.op = ariane_pkg::ZIP;
                 else illegal_instr_bm = 1'b1;
@@ -929,8 +938,14 @@ module decoder
                   instruction_o.op = ariane_pkg::REV8;
                 else if (instr.instr[31:20] == 12'b011010011000)
                   instruction_o.op = ariane_pkg::REV8;
-                else if (instr.instr[31:26] == 6'b010_010) instruction_o.op = ariane_pkg::BEXTI;
-                else if (instr.instr[31:26] == 6'b011_000) instruction_o.op = ariane_pkg::RORI;
+                else if (CVA6Cfg.IS_XLEN64 && instr.instr[31:26] == 6'b010_010)
+                  instruction_o.op = ariane_pkg::BEXTI;
+                else if (CVA6Cfg.IS_XLEN32 && instr.instr[31:25] == 7'b010_0100)
+                  instruction_o.op = ariane_pkg::BEXTI;
+                else if (CVA6Cfg.IS_XLEN64 && instr.instr[31:26] == 6'b011_000)
+                  instruction_o.op = ariane_pkg::RORI;
+                else if (CVA6Cfg.IS_XLEN32 && instr.instr[31:25] == 7'b011_0000)
+                  instruction_o.op = ariane_pkg::RORI;
                 else if (CVA6Cfg.ZKN && instr.instr[31:20] == 12'b011010000111)
                   instruction_o.op = ariane_pkg::BREV8;
                 else if (CVA6Cfg.ZKN && instr.instr[31:20] == 12'b000010001111)

