      .acc_mmu_req_t(acc_mmu_req_t),
      .acc_mmu_resp_t(acc_mmu_resp_t)
  ) dut (.*);

  task automatic init_inputs;
    begin
      clk_i = 1'b0;
      rst_ni = 1'b1;
      flush_i = 1'b0;
      debug_mode_i = 1'b0;
      rs1_forwarding_i = '0;
      rs2_forwarding_i = '0;
      fu_data_i = '{default: '0};
      pc_i = '0;
      is_zcmt_i = 1'b0;
      is_compressed_instr_i = 1'b0;
      tinst_i = '0;
