      flush_tlb_i = 1'b0;
      flush_tlb_vvma_i = 1'b0;
      flush_tlb_gvma_i = 1'b0;
      priv_lvl_i = riscv::PRIV_LVL_M;
      v_i = 1'b0;
      ld_st_priv_lvl_i = riscv::PRIV_LVL_M;
      ld_st_v_i = 1'b0;
      sum_i = 1'b0;
      vs_sum_i = 1'b0;
      mxr_i = 1'b0;
      vmxr_i = 1'b0;
      satp_ppn_i = '0;
      asid_i = '0;
      vsatp_ppn_i = '0;
      vs_asid_i = '0;
      hgatp_ppn_i = '0;
