  endtask

  task automatic check_case(
      input logic expected_gva,
      input logic [31:0] expected_instr,
      input logic [CVA6Cfg.TRANS_ID_BITS-1:0] expected_id
  );
    begin
      init_inputs();
      v_i = expected_gva;
      x_valid_i[0] = 1'b1;
      x_transaction_rejected_i = 1'b1;
      x_off_instr_i = expected_instr;
      fu_data_i[0].trans_id = expected_id;
      #1;

      if (x_ready_o !== 1'b1) begin
        $fatal(1, "x_ready_o must be asserted");
      end
      if (x_result_ready_o !== 1'b1) begin
        $fatal(1, "x_result_ready_o must be asserted");
      end
      if (x_valid_o !== 1'b1) begin
        $fatal(1, "x_valid_o must be asserted for illegal CVXIF instruction");
      end
      if (x_trans_id_o !== expected_id) begin
        $fatal(1, "x_trans_id_o mismatch got %0d expected %0d", x_trans_id_o, expected_id);
      end
      if (x_exception_o.valid !== 1'b1 || x_exception_o.cause !== riscv::ILLEGAL_INSTR) begin
        $fatal(1, "illegal instruction exception metadata mismatch");
      end
      if (CVA6Cfg.TvalEn && x_exception_o.tval !== expected_instr) begin
        $fatal(1, "tval mismatch got 0x%08x expected 0x%08x", x_exception_o.tval, expected_instr);
      end
      if (x_exception_o.tval2 !== '0) begin
        $fatal(1, "tval2 must be zero, got 0x%0h", x_exception_o.tval2);
      end
      if (x_exception_o.tinst !== '0) begin
        $fatal(1, "tinst must be zero, got 0x%08x", x_exception_o.tinst);
      end
      if (x_exception_o.gva !== expected_gva) begin
        $fatal(1, "gva mismatch got %0d expected %0d", x_exception_o.gva, expected_gva);
      end
    end
  endtask

  initial begin
    check_case(1'b0, 32'hDEAD_BEEF, CVA6Cfg.TRANS_ID_BITS'(1));
    check_case(1'b1, 32'hCAFE_BABE, CVA6Cfg.TRANS_ID_BITS'(2));
    $display("TB_PASS: ex_stage propagates fully initialized CVXIF exception fields");
    $finish;
  end
endmodule
