    logic [CVA6Cfg.DCACHE_INDEX_WIDTH-1:0] address_index;
    logic [CVA6Cfg.DCACHE_TAG_WIDTH-1:0]   address_tag;
    logic [CVA6Cfg.XLEN-1:0]               data_wdata;
    logic [CVA6Cfg.DCACHE_USER_WIDTH-1:0]  data_wuser;
    logic                                  data_req;
    logic                                  data_we;
    logic [(CVA6Cfg.XLEN/8)-1:0]           data_be;
    logic [1:0]                            data_size;
    logic [CVA6Cfg.DcacheIdWidth-1:0]      data_id;
    logic                                  kill_req;
    logic                                  tag_valid;
  };

  localparam type dcache_req_o_t = struct packed {
    logic                                 data_gnt;
    logic                                 data_rvalid;
    logic [CVA6Cfg.DcacheIdWidth-1:0]     data_rid;
    logic [CVA6Cfg.XLEN-1:0]              data_rdata;
    logic [CVA6Cfg.DCACHE_USER_WIDTH-1:0] data_ruser;
  };

  localparam logic [CVA6Cfg.VLEN-1:0] TEST_VADDR = 64'h0000_0000_0040_1000;
  localparam logic [CVA6Cfg.ASID_WIDTH-1:0] HOST_ASID  = CVA6Cfg.ASID_WIDTH'(16'h12);
  localparam logic [CVA6Cfg.ASID_WIDTH-1:0] GUEST_ASID = CVA6Cfg.ASID_WIDTH'(16'h34);

  localparam logic [CVA6Cfg.PPNW-1:0] ROOT_PPN = CVA6Cfg.PPNW'(44'h100);
  localparam logic [CVA6Cfg.PPNW-1:0] L1_PPN   = CVA6Cfg.PPNW'(44'h101);
  localparam logic [CVA6Cfg.PPNW-1:0] L0_PPN   = CVA6Cfg.PPNW'(44'h102);
  localparam logic [8:0] VPN2 = TEST_VADDR[38:30];
  localparam logic [8:0] VPN1 = TEST_VADDR[29:21];
  localparam logic [8:0] VPN0 = TEST_VADDR[20:12];

  function automatic logic [63:0] make_table_pte(input logic [CVA6Cfg.PPNW-1:0] ppn);
    return ({20'b0, ppn} << 10) | 64'h1;
  endfunction

  function automatic logic [63:0] make_leaf_pte(input logic [CVA6Cfg.PPNW-1:0] ppn);
    return ({20'b0, ppn} << 10) | 64'h53;
  endfunction

  function automatic logic [CVA6Cfg.PLEN-1:0] pte_addr(
      input logic [CVA6Cfg.PPNW-1:0] base_ppn,
      input logic [8:0] vpn_index
  );
    logic [CVA6Cfg.PLEN-1:0] base_addr;
    begin
      base_addr = {base_ppn, 12'b0};
      return base_addr + (CVA6Cfg.PLEN'(vpn_index) << 3);
    end
  endfunction

  localparam logic [CVA6Cfg.PLEN-1:0] ROOT_PTE_ADDR = pte_addr(ROOT_PPN, VPN2);
  localparam logic [CVA6Cfg.PLEN-1:0] L1_PTE_ADDR   = pte_addr(L1_PPN, VPN1);
  localparam logic [CVA6Cfg.PLEN-1:0] L0_PTE_ADDR   = pte_addr(L0_PPN, VPN0);

  logic clk_i;
  logic rst_ni;
  logic flush_i;
  logic enable_translation_i;
  logic enable_g_translation_i;
  logic en_ld_st_translation_i;
  logic en_ld_st_g_translation_i;

  icache_arsp_t icache_areq_i;
  icache_areq_t icache_areq_o;
  exception_t misaligned_ex_i;
  logic lsu_req_i;
  logic [CVA6Cfg.VLEN-1:0] lsu_vaddr_i;
  logic [31:0] lsu_tinst_i;
  logic lsu_is_store_i;
  logic csr_hs_ld_st_inst_o;
  logic lsu_dtlb_hit_o;
  logic [CVA6Cfg.PPNW-1:0] lsu_dtlb_ppn_o;
  logic lsu_valid_o;
  logic [CVA6Cfg.PLEN-1:0] lsu_paddr_o;
  exception_t lsu_exception_o;
  riscv::priv_lvl_t priv_lvl_i;
  logic v_i;
  riscv::priv_lvl_t ld_st_priv_lvl_i;
  logic ld_st_v_i;
  logic sum_i;
  logic vs_sum_i;
  logic mxr_i;
  logic vmxr_i;
  logic hlvx_inst_i;
  logic hs_ld_st_inst_i;
  logic [CVA6Cfg.PPNW-1:0] satp_ppn_i;
  logic [CVA6Cfg.PPNW-1:0] vsatp_ppn_i;
  logic [CVA6Cfg.PPNW-1:0] hgatp_ppn_i;
  logic [CVA6Cfg.ASID_WIDTH-1:0] asid_i;
  logic [CVA6Cfg.ASID_WIDTH-1:0] vs_asid_i;
  logic [CVA6Cfg.ASID_WIDTH-1:0] asid_to_be_flushed_i;
  logic [CVA6Cfg.VMID_WIDTH-1:0] vmid_i;
  logic [CVA6Cfg.VMID_WIDTH-1:0] vmid_to_be_flushed_i;
  logic [CVA6Cfg.VLEN-1:0] vaddr_to_be_flushed_i;
  logic [CVA6Cfg.GPLEN-1:0] gpaddr_to_be_flushed_i;
  logic flush_tlb_i;
  logic flush_tlb_vvma_i;
  logic flush_tlb_gvma_i;
  logic itlb_miss_o;
  logic dtlb_miss_o;
  dcache_req_o_t req_port_i;
  dcache_req_i_t req_port_o;
  riscv::pmpcfg_t [CVA6Cfg.NrPMPEntries-1:0] pmpcfg_i;
  logic [CVA6Cfg.NrPMPEntries-1:0][CVA6Cfg.PLEN-3:0] pmpaddr_i;

  logic [63:0] root_pte_q;
  logic [63:0] l1_pte_q;
  logic [63:0] leaf_pte_q;
  logic rsp_valid_q;
  logic [CVA6Cfg.XLEN-1:0] rsp_data_q;
  logic second_hit_seen;
  integer ptw_req_count;

  function automatic logic [63:0] read_mem64(input logic [CVA6Cfg.PLEN-1:0] addr);
    begin
      if (addr == ROOT_PTE_ADDR) begin
        return root_pte_q;
      end else if (addr == L1_PTE_ADDR) begin
        return l1_pte_q;
      end else if (addr == L0_PTE_ADDR) begin
        return leaf_pte_q;
      end
      return 64'h0;
    end
  endfunction

  always #5 clk_i = ~clk_i;

  always_comb begin
    req_port_i = '0;
    req_port_i.data_gnt    = req_port_o.data_req;
    req_port_i.data_rvalid = rsp_valid_q;
    req_port_i.data_rdata  = rsp_data_q;
  end

  always_ff @(posedge clk_i or negedge rst_ni) begin
    logic [CVA6Cfg.PLEN-1:0] req_addr;
    if (!rst_ni) begin
      rsp_valid_q   <= 1'b0;
      rsp_data_q    <= '0;
      ptw_req_count <= 0;
    end else begin
      rsp_valid_q <= req_port_o.data_req;
      req_addr = {req_port_o.address_tag, req_port_o.address_index};
      rsp_data_q <= read_mem64(req_addr);
      if (req_port_o.data_req) begin
        ptw_req_count <= ptw_req_count + 1;
        $display("PTW read %0d addr=%h", ptw_req_count + 1, req_addr);
      end
    end
  end

  task automatic start_guest_load;
    begin
      @(negedge clk_i);
      lsu_vaddr_i = TEST_VADDR;
      lsu_req_i   = 1'b1;
    end
  endtask

  task automatic stop_guest_load;
    begin
      @(negedge clk_i);
      lsu_req_i = 1'b0;
    end
  endtask

  task automatic pulse_guest_load(output logic hit_seen);
    begin
      start_guest_load();
      @(posedge clk_i);
      hit_seen = lsu_dtlb_hit_o;
      stop_guest_load();
    end
  endtask

  task automatic wait_for_dtlb_hit;
    int cycles;
    begin
      for (cycles = 0; cycles < 80; cycles++) begin
        @(posedge clk_i);
        if (lsu_dtlb_hit_o) begin
          return;
        end
        if (ptw_req_count > 3) begin
          $fatal(1, "Guest load restarted the page walk before hitting in the DTLB, ptw_req_count=%0d", ptw_req_count);
        end
      end
      $fatal(1, "Timed out waiting for the guest load to hit in the DTLB, ptw_req_count=%0d", ptw_req_count);
    end
  endtask

  cva6_mmu #(
    .CVA6Cfg(CVA6Cfg),
    .icache_areq_t(icache_areq_t),
    .icache_arsp_t(icache_arsp_t),
    .icache_dreq_t(icache_dreq_t),
    .icache_drsp_t(icache_drsp_t),
    .dcache_req_i_t(dcache_req_i_t),
    .dcache_req_o_t(dcache_req_o_t),
    .exception_t(exception_t),
    .HYP_EXT(HYP_EXT)
  ) dut (
    .clk_i,
    .rst_ni,
    .flush_i,
    .enable_translation_i,
    .enable_g_translation_i,
    .en_ld_st_translation_i,
    .en_ld_st_g_translation_i,
    .icache_areq_i,
    .icache_areq_o,
    .misaligned_ex_i,
    .lsu_req_i,
    .lsu_vaddr_i,
    .lsu_tinst_i,
    .lsu_is_store_i,
    .csr_hs_ld_st_inst_o,
    .lsu_dtlb_hit_o,
    .lsu_dtlb_ppn_o,
    .lsu_valid_o,
    .lsu_paddr_o,
    .lsu_exception_o,
    .priv_lvl_i,
    .v_i,
    .ld_st_priv_lvl_i,
    .ld_st_v_i,
    .sum_i,
    .vs_sum_i,
    .mxr_i,
    .vmxr_i,
    .hlvx_inst_i,
    .hs_ld_st_inst_i,
    .satp_ppn_i,
    .vsatp_ppn_i,
    .hgatp_ppn_i,
    .asid_i,
    .vs_asid_i,
    .asid_to_be_flushed_i,
    .vmid_i,
    .vmid_to_be_flushed_i,
    .vaddr_to_be_flushed_i,
    .gpaddr_to_be_flushed_i,
    .flush_tlb_i,
    .flush_tlb_vvma_i,
    .flush_tlb_gvma_i,
    .itlb_miss_o,
    .dtlb_miss_o,
    .req_port_i,
    .req_port_o,
    .pmpcfg_i,
    .pmpaddr_i
  );

  initial begin
    clk_i                    = 1'b0;
    rst_ni                   = 1'b0;
    flush_i                  = 1'b0;
    enable_translation_i     = 1'b0;
    enable_g_translation_i   = 1'b0;
    en_ld_st_translation_i   = 1'b1;
    en_ld_st_g_translation_i = 1'b0;
    icache_areq_i            = '0;
    misaligned_ex_i          = '0;
    lsu_req_i                = 1'b0;
    lsu_vaddr_i              = '0;
    lsu_tinst_i              = '0;
    lsu_is_store_i           = 1'b0;
    priv_lvl_i               = riscv::PRIV_LVL_S;
    v_i                      = 1'b0;
    ld_st_priv_lvl_i         = riscv::PRIV_LVL_U;
    ld_st_v_i                = 1'b1;
    sum_i                    = 1'b0;
    vs_sum_i                 = 1'b0;
    mxr_i                    = 1'b0;
    vmxr_i                   = 1'b0;
    hlvx_inst_i              = 1'b0;
    hs_ld_st_inst_i          = 1'b0;
    satp_ppn_i               = '0;
    vsatp_ppn_i              = ROOT_PPN;
    hgatp_ppn_i              = '0;
    asid_i                   = HOST_ASID;
    vs_asid_i                = GUEST_ASID;
    asid_to_be_flushed_i     = '0;
    vmid_i                   = '0;
    vmid_to_be_flushed_i     = '0;
    vaddr_to_be_flushed_i    = '0;
    gpaddr_to_be_flushed_i   = '0;
    flush_tlb_i              = 1'b0;
    flush_tlb_vvma_i         = 1'b0;
    flush_tlb_gvma_i         = 1'b0;
    pmpcfg_i                 = '0;
    pmpaddr_i                = '0;
    pmpcfg_i[0].locked        = 1'b0;
    pmpcfg_i[0].reserved      = '0;
    pmpcfg_i[0].addr_mode     = riscv::NAPOT;
    pmpcfg_i[0].access_type.r = 1'b1;
    pmpcfg_i[0].access_type.w = 1'b1;
    pmpcfg_i[0].access_type.x = 1'b1;
    pmpaddr_i[0]              = '1;

    root_pte_q = make_table_pte(L1_PPN);
    l1_pte_q   = make_table_pte(L0_PPN);
    leaf_pte_q = make_leaf_pte(CVA6Cfg.PPNW'(44'h200));
    second_hit_seen = 1'b0;

    repeat (3) @(posedge clk_i);
    rst_ni = 1'b1;
    repeat (2) @(posedge clk_i);

    $display("Holding the first guest load until the translated entry appears in the DTLB");
    start_guest_load();
    wait_for_dtlb_hit();
    stop_guest_load();
    if (ptw_req_count != 3) begin
      $fatal(1, "Expected one Sv39 page walk with 3 PTW reads, saw %0d", ptw_req_count);
    end

    repeat (2) @(posedge clk_i);
    $display("Triggering the second guest load; it must hit in the DTLB using the guest ASID");
    pulse_guest_load(second_hit_seen);
    if (!second_hit_seen) begin
      $fatal(1, "Second guest load missed in the DTLB with host_asid=%0h guest_asid=%0h", HOST_ASID, GUEST_ASID);
    end

    repeat (3) @(posedge clk_i);
    if (ptw_req_count != 3) begin
      $fatal(1, "Second guest load started another page walk, ptw_req_count=%0d", ptw_req_count);
    end

    $display("PASS guest ASID keeps the translated entry in the DTLB");
    $finish;
  end
endmodule
EOF

