#!/bin/bash
cd /home/cva6 || exit 1

TEST_NAME="cvxif_off_instr_issue_read_operands"
TB_DIR="/home/cva6/.tb_${TEST_NAME}"
TB_SV="${TB_DIR}/issue_read_operands_tb.sv"
RUN_LOG="${TB_DIR}/run.log"
OBJ_DIR="${TB_DIR}/obj_dir"
TOP="issue_read_operands_tb"

rm -rf "$TB_DIR"
mkdir -p "$TB_DIR"

cat > "$TB_SV" <<'EOF'
`include "cvxif_types.svh"

module issue_read_operands_tb;
  import ariane_pkg::*;

  localparam config_pkg::cva6_cfg_t CVA6Cfg = build_config_pkg::build_config(cva6_config_pkg::cva6_cfg);

  localparam type branchpredict_sbe_t = struct packed {
    cf_t                     cf;
    logic [CVA6Cfg.VLEN-1:0] predict_address;
  };

  localparam type exception_t = struct packed {
    logic [CVA6Cfg.XLEN-1:0] cause;
    logic [CVA6Cfg.XLEN-1:0] tval;
    logic [CVA6Cfg.GPLEN-1:0] tval2;
    logic [31:0] tinst;
    logic gva;
    logic valid;
  };

  localparam type scoreboard_entry_t = struct packed {
    logic [CVA6Cfg.VLEN-1:0] pc;
    logic [CVA6Cfg.TRANS_ID_BITS-1:0] trans_id;
    fu_t fu;
    fu_op op;
    logic [REG_ADDR_SIZE-1:0] rs1;
    logic [REG_ADDR_SIZE-1:0] rs2;
    logic [REG_ADDR_SIZE-1:0] rd;
    logic [CVA6Cfg.XLEN-1:0] result;
    logic valid;
    logic use_imm;
    logic use_zimm;
    logic use_pc;
    exception_t ex;
    branchpredict_sbe_t bp;
    logic is_compressed;
    logic is_macro_instr;
    logic is_last_macro_instr;
    logic is_double_rd_macro_instr;
    logic vfp;
    logic is_zcmt;
  };

  localparam type writeback_t = struct packed {
    logic valid;
    logic [CVA6Cfg.XLEN-1:0] data;
    logic ex_valid;
    logic [CVA6Cfg.TRANS_ID_BITS-1:0] trans_id;
  };

  localparam type fu_data_t = struct packed {
    fu_t fu;
    fu_op operation;
    logic [CVA6Cfg.XLEN-1:0] operand_a;
    logic [CVA6Cfg.XLEN-1:0] operand_b;
    logic [CVA6Cfg.XLEN-1:0] imm;
    logic [CVA6Cfg.TRANS_ID_BITS-1:0] trans_id;
  };

  typedef logic [(CVA6Cfg.NrRgprPorts == 3 ? CVA6Cfg.XLEN : CVA6Cfg.FLen)-1:0] rs3_len_t;

  localparam type readregflags_t = `READREGFLAGS_T(CVA6Cfg);
  localparam type writeregflags_t = `WRITEREGFLAGS_T(CVA6Cfg);
  localparam type id_t = `ID_T(CVA6Cfg);
  localparam type hartid_t = `HARTID_T(CVA6Cfg);
  localparam type x_issue_req_t = `X_ISSUE_REQ_T(CVA6Cfg, hartid_t, id_t);
  localparam type x_issue_resp_t = `X_ISSUE_RESP_T(CVA6Cfg, writeregflags_t, readregflags_t);
  localparam type x_register_t = `X_REGISTER_T(CVA6Cfg, hartid_t, id_t, readregflags_t);
  localparam type x_commit_t = `X_COMMIT_T(CVA6Cfg, hartid_t, id_t);

  localparam type forwarding_t = struct packed {
    logic [CVA6Cfg.NR_SB_ENTRIES-1:0] still_issued;
    logic [CVA6Cfg.TRANS_ID_BITS-1:0] issue_pointer;
    writeback_t [CVA6Cfg.NrWbPorts-1:0] wb;
    scoreboard_entry_t [CVA6Cfg.NR_SB_ENTRIES-1:0] sbe;
  };

  localparam logic [31:0] TRIGGER_INSTR = 32'h0002b007;

  logic clk_i;
  logic rst_ni;
  logic flush_i;
  logic stall_i;
  scoreboard_entry_t [CVA6Cfg.NrIssuePorts-1:0] issue_instr_i;
  scoreboard_entry_t [CVA6Cfg.NrIssuePorts-1:0] issue_instr_i_prev;
  logic [CVA6Cfg.NrIssuePorts-1:0][31:0] orig_instr_i;
  logic [CVA6Cfg.NrIssuePorts-1:0] issue_instr_valid_i;
  logic [CVA6Cfg.NrIssuePorts-1:0] issue_ack_o;
  forwarding_t fwd_i;
  fu_data_t [CVA6Cfg.NrIssuePorts-1:0] fu_data_o;
  logic [CVA6Cfg.NrIssuePorts-1:0][CVA6Cfg.VLEN-1:0] rs1_forwarding_o;
  logic [CVA6Cfg.NrIssuePorts-1:0][CVA6Cfg.VLEN-1:0] rs2_forwarding_o;
  logic [CVA6Cfg.VLEN-1:0] pc_o;
  logic is_zcmt_o;
  logic is_compressed_instr_o;
  logic flu_ready_i;
  logic [CVA6Cfg.NrIssuePorts-1:0] alu_valid_o;
  logic [CVA6Cfg.NrIssuePorts-1:0] branch_valid_o;
  logic [CVA6Cfg.NrIssuePorts-1:0][31:0] tinst_o;
  branchpredict_sbe_t branch_predict_o;
  logic lsu_ready_i;
  logic [CVA6Cfg.NrIssuePorts-1:0] lsu_valid_o;
  logic [CVA6Cfg.NrIssuePorts-1:0] mult_valid_o;
  logic fpu_ready_i;
  logic [CVA6Cfg.NrIssuePorts-1:0] fpu_valid_o;
  logic [1:0] fpu_fmt_o;
  logic [2:0] fpu_rm_o;
  logic [CVA6Cfg.NrIssuePorts-1:0] alu2_valid_o;
  logic [CVA6Cfg.NrIssuePorts-1:0] csr_valid_o;
