  issue_read_operands #(
    .CVA6Cfg(CVA6Cfg),
    .branchpredict_sbe_t(branchpredict_sbe_t),
    .fu_data_t(fu_data_t),
    .scoreboard_entry_t(scoreboard_entry_t),
    .forwarding_t(forwarding_t),
    .writeback_t(writeback_t),
    .rs3_len_t(rs3_len_t),
    .x_issue_req_t(x_issue_req_t),
    .x_issue_resp_t(x_issue_resp_t),
    .x_register_t(x_register_t),
    .x_commit_t(x_commit_t)
  ) dut (
    .clk_i(clk_i),
    .rst_ni(rst_ni),
    .flush_i(flush_i),
    .stall_i(stall_i),
    .issue_instr_i(issue_instr_i),
    .issue_instr_i_prev(issue_instr_i_prev),
    .orig_instr_i(orig_instr_i),
    .issue_instr_valid_i(issue_instr_valid_i),
    .issue_ack_o(issue_ack_o),
    .fwd_i(fwd_i),
    .fu_data_o(fu_data_o),
    .rs1_forwarding_o(rs1_forwarding_o),
    .rs2_forwarding_o(rs2_forwarding_o),
    .pc_o(pc_o),
    .is_zcmt_o(is_zcmt_o),
    .is_compressed_instr_o(is_compressed_instr_o),
    .flu_ready_i(flu_ready_i),
    .alu_valid_o(alu_valid_o),
    .branch_valid_o(branch_valid_o),
    .tinst_o(tinst_o),
    .branch_predict_o(branch_predict_o),
    .lsu_ready_i(lsu_ready_i),
    .lsu_valid_o(lsu_valid_o),
    .mult_valid_o(mult_valid_o),
    .fpu_ready_i(fpu_ready_i),
    .fpu_valid_o(fpu_valid_o),
    .fpu_fmt_o(fpu_fmt_o),
    .fpu_rm_o(fpu_rm_o),
    .alu2_valid_o(alu2_valid_o),
    .csr_valid_o(csr_valid_o),
    .cvxif_valid_o(cvxif_valid_o),
    .cvxif_ready_i(cvxif_ready_i),
    .cvxif_off_instr_o(cvxif_off_instr_o),
    .hart_id_i(hart_id_i),
    .x_issue_ready_i(x_issue_ready_i),
    .x_issue_resp_i(x_issue_resp_i),
    .x_issue_valid_o(x_issue_valid_o),
    .x_issue_req_o(x_issue_req_o),
    .x_register_ready_i(x_register_ready_i),
    .x_register_valid_o(x_register_valid_o),
    .x_register_o(x_register_o),
    .x_commit_valid_o(x_commit_valid_o),
    .x_commit_o(x_commit_o),
    .x_transaction_accepted_o(x_transaction_accepted_o),
    .x_transaction_rejected_o(x_transaction_rejected_o),
    .x_issue_writeback_o(x_issue_writeback_o),
    .x_id_o(x_id_o),
    .waddr_i(waddr_i),
    .wdata_i(wdata_i),
    .we_gpr_i(we_gpr_i),
    .we_fpr_i(we_fpr_i),
    .stall_issue_o(stall_issue_o),
    .rvfi_rs1_o(rvfi_rs1_o),
    .rvfi_rs2_o(rvfi_rs2_o)
  );

  always #5 clk_i = ~clk_i;

  initial begin
    clk_i = 1'b0;
    rst_ni = 1'b0;
    flush_i = 1'b0;
    stall_i = 1'b0;
    issue_instr_i = '{default: '0};
    issue_instr_i_prev = '{default: '0};
    orig_instr_i = '{default: '0};
    issue_instr_valid_i = '0;
    fwd_i = '0;
    flu_ready_i = 1'b1;
    lsu_ready_i = 1'b1;
    fpu_ready_i = 1'b1;
    cvxif_ready_i = 1'b1;
    hart_id_i = '0;
    x_issue_ready_i = 1'b1;
    x_issue_resp_i = '0;
    x_issue_resp_i.accept = 1'b1;
    x_issue_resp_i.register_read = '0;
    x_register_ready_i = 1'b1;
    waddr_i = '0;
    wdata_i = '0;
    we_gpr_i = '0;
    we_fpr_i = '0;

    repeat (2) @(posedge clk_i);
    rst_ni = 1'b1;

    issue_instr_i[0].fu = CVXIF;
    issue_instr_i[0].op = OFFLOAD;
    issue_instr_i[0].trans_id = '0;
    issue_instr_i[0].ex.valid = 1'b0;
    orig_instr_i[0] = TRIGGER_INSTR;
    issue_instr_valid_i[0] = 1'b1;

    @(posedge clk_i);
    #1;

    if (issue_ack_o[0] !== 1'b1) begin
      $fatal(1, "Expected issue_ack_o[0]=1, got %0b", issue_ack_o[0]);
    end
    if (cvxif_valid_o[0] !== 1'b1) begin
      $fatal(1, "Expected cvxif_valid_o[0]=1, got %0b", cvxif_valid_o[0]);
    end
    if (cvxif_off_instr_o !== TRIGGER_INSTR) begin
      $fatal(1, "Expected cvxif_off_instr_o=0x%08x, got 0x%08x", TRIGGER_INSTR, cvxif_off_instr_o);
    end

    $display("Observed cvxif_off_instr_o=0x%08x", cvxif_off_instr_o);
    $finish;
  end
endmodule
EOF

