#!/bin/bash
cd /home/cva6
set -u

TEST_NAME="compressed_decoder_csh_bit6_illegal"

if [[ -f /etc/cva6_tools_path.sh ]]; then
  # Load tool paths selected during prepare.
  source /etc/cva6_tools_path.sh
fi

set +e
timeout 1200s /bin/bash <<'EOF'
set -euo pipefail

cd /home/cva6
TB_DIR="/home/cva6/.tb_csh_bit6_illegal"
rm -rf "$TB_DIR"
mkdir -p "$TB_DIR"

cat > "$TB_DIR/decoder_tb.sv" <<'SV'
module decoder_tb (
    input  logic [31:0] instr_i,
    output logic [31:0] instr_o,
    output logic        illegal_instr_o,
    output logic        is_macro_instr_o,
    output logic        is_compressed_o,
    output logic        is_zcmt_instr_o
);
  localparam config_pkg::cva6_cfg_t CVA6Cfg = build_config_pkg::build_config(cva6_config_pkg::cva6_cfg);

  compressed_decoder #(
      .CVA6Cfg(CVA6Cfg)
  ) dut (
      .instr_i(instr_i),
      .instr_o(instr_o),
      .illegal_instr_o(illegal_instr_o),
      .is_macro_instr_o(is_macro_instr_o),
      .is_compressed_o(is_compressed_o),
      .is_zcmt_instr_o(is_zcmt_instr_o)
  );
endmodule
SV

cat > "$TB_DIR/decoder_tb.cpp" <<'CPP'
#include "Vdecoder_tb.h"
#include "verilated.h"
#include <cstdint>
#include <iostream>

namespace {
struct TestCase {
  const char* name;
  uint32_t instr;
  uint32_t expected_instr;
  int expected_illegal;
};
}  // namespace

int main(int argc, char** argv) {
  Verilated::commandArgs(argc, argv);
  Vdecoder_tb top;

  const TestCase tests[] = {
      {"legal_c_sh",   0x00008c3cU, 0x00f41123U, 0},
      {"illegal_c_sh", 0x00008c7cU, 0x00000000U, 1},
  };

  for (const auto& tc : tests) {
    top.instr_i = tc.instr;
    top.eval();

    if (static_cast<int>(top.illegal_instr_o) != tc.expected_illegal) {
      std::cerr << tc.name << ": illegal_instr_o=" << int(top.illegal_instr_o)
                << " expected=" << tc.expected_illegal << std::endl;
      return 1;
    }

    if (top.is_compressed_o != 1) {
      std::cerr << tc.name << ": is_compressed_o=" << int(top.is_compressed_o)
                << " expected=1" << std::endl;
      return 1;
    }

    if (!tc.expected_illegal && top.instr_o != tc.expected_instr) {
      std::cerr << tc.name << ": instr_o=0x" << std::hex << top.instr_o
                << " expected=0x" << tc.expected_instr << std::endl;
      return 1;
    }
  }

  return 0;
}
CPP

