#!/bin/bash
set -u

cd /home/cva6 || exit 1

TB_DIR=/home/cva6/.tb_iti_latch
LOG_FILE="$TB_DIR/test.log"
VERILATOR_BIN=/tools/verilator/bin/verilator

rm -rf "$TB_DIR"
mkdir -p "$TB_DIR"

cat > "$TB_DIR/iti_latch_tb.sv" <<'EOF'
`timescale 1ns/1ps

`include "rvfi_types.svh"
`include "iti_types.svh"

module iti_latch_tb;
  localparam config_pkg::cva6_cfg_t CVA6Cfg = build_config_pkg::build_config(
      cva6_config_pkg::cva6_cfg
  );
  localparam int unsigned CauseLen = iti_pkg::CAUSE_LEN;
  localparam int unsigned ItypeLen = iti_pkg::ITYPE_LEN;
  localparam int unsigned IretireLen = iti_pkg::IRETIRE_LEN;
  localparam type rvfi_to_iti_t = `RVFI_TO_ITI_T(CVA6Cfg);
  localparam type iti_to_encoder_t = `ITI_TO_ENCODER_T(CVA6Cfg);

  logic clk_i = 1'b0;
  logic rst_ni = 1'b0;
  logic [CVA6Cfg.NrCommitPorts-1:0] valid_i;
  rvfi_to_iti_t rvfi_to_iti_i;
  logic [CVA6Cfg.NrCommitPorts-1:0] valid_o;
  iti_to_encoder_t iti_to_encoder_o;

  always #5 clk_i = ~clk_i;

  cva6_iti #(
      .CVA6Cfg(CVA6Cfg),
      .CAUSE_LEN(CauseLen),
      .ITYPE_LEN(ItypeLen),
      .IRETIRE_LEN(IretireLen),
      .rvfi_to_iti_t(rvfi_to_iti_t),
      .iti_to_encoder_t(iti_to_encoder_t)
  ) dut (
      .clk_i(clk_i),
      .rst_ni(rst_ni),
      .valid_i(valid_i),
      .rvfi_to_iti_i(rvfi_to_iti_i),
      .valid_o(valid_o),
      .iti_to_encoder_o(iti_to_encoder_o)
  );

  task automatic clear_inputs();
    begin
      valid_i = '0;
      rvfi_to_iti_i = '0;
      rvfi_to_iti_i.priv_lvl = riscv::PRIV_LVL_M;
    end
  endtask

  initial begin
    clear_inputs();

    repeat (2) @(posedge clk_i);
    rst_ni = 1'b1;

    @(negedge clk_i);
    clear_inputs();
    valid_i[0] = 1'b1;
    rvfi_to_iti_i.valid[0] = 1'b1;
    rvfi_to_iti_i.pc[0] = 32'h0000_1000;
    rvfi_to_iti_i.op[0] = ariane_pkg::JALR;
    rvfi_to_iti_i.is_compressed[0] = 1'b0;
    rvfi_to_iti_i.branch_valid[0] = 1'b0;
    rvfi_to_iti_i.is_taken[0] = 1'b0;
    rvfi_to_iti_i.ex_valid = 1'b0;
    rvfi_to_iti_i.cause = '0;
    rvfi_to_iti_i.tval = '0;
    rvfi_to_iti_i.cycles = 64'd10;

    @(posedge clk_i);
    #1;
    if (valid_o[0] !== 1'b1) begin
      $fatal(1, "expected valid_o high after special instruction, got %b", valid_o[0]);
    end

    @(negedge clk_i);
    clear_inputs();
    rvfi_to_iti_i.cycles = 64'd11;

    @(posedge clk_i);
    #1;
    if (valid_o[0] !== 1'b0) begin
      $fatal(1, "valid_o did not clear after special instruction, got %b", valid_o[0]);
    end

    $display("iti_latch_tb PASS");
    $finish;
  end
endmodule
EOF

cat > "$TB_DIR/sim_main.cpp" <<'EOF'
#include "Viti_latch_tb.h"
#include "verilated.h"

int main(int argc, char** argv) {
  Verilated::commandArgs(argc, argv);

  Viti_latch_tb top;
  while (!Verilated::gotFinish()) {
    top.eval();
    Verilated::timeInc(1);
  }

  return 0;
