module pmp_fetch_guard_tb;
  timeunit 1ns;
  timeprecision 1ps;

  localparam config_pkg::cva6_cfg_t TestCfg = '{
      XLEN:         32'd64,
      VLEN:         32'd64,
      PLEN:         32'd56,
      GPLEN:        32'd8,
      TvalEn:       1'b1,
      RVH:          1'b0,
      NrPMPEntries: 32'd1
  };

  typedef struct packed {
    logic [TestCfg.XLEN-1:0] cause;
    logic [TestCfg.XLEN-1:0] tval;
    logic [TestCfg.GPLEN-1:0] tval2;
    logic [31:0] tinst;
    logic gva;
    logic valid;
  } exception_t;

  typedef struct packed {
    logic fetch_valid;
    logic [TestCfg.PLEN-1:0] fetch_paddr;
    exception_t fetch_exception;
  } icache_areq_t;

  logic clk_i;
  logic rst_ni;
  icache_areq_t icache_areq_i;
  icache_areq_t icache_areq_o;
  logic [TestCfg.VLEN-1:0] icache_fetch_vaddr_i;
  logic lsu_valid_i;
  logic [TestCfg.PLEN-1:0] lsu_paddr_i;
  logic [TestCfg.VLEN-1:0] lsu_vaddr_i;
  exception_t lsu_exception_i;
  logic lsu_is_store_i;
  logic lsu_valid_o;
  logic [TestCfg.PLEN-1:0] lsu_paddr_o;
  exception_t lsu_exception_o;
  riscv::priv_lvl_t priv_lvl_i;
  logic v_i;
  riscv::priv_lvl_t ld_st_priv_lvl_i;
  logic ld_st_v_i;
  riscv::pmpcfg_t [ariane_pkg::avoid_neg(TestCfg.NrPMPEntries-1):0] pmpcfg_i;
  logic [ariane_pkg::avoid_neg(TestCfg.NrPMPEntries-1):0][TestCfg.PLEN-3:0] pmpaddr_i;

  pmp_data_if #(
      .CVA6Cfg(TestCfg),
      .icache_areq_t(icache_areq_t),
      .exception_t(exception_t)
  ) dut (
      .clk_i(clk_i),
      .rst_ni(rst_ni),
      .icache_areq_i(icache_areq_i),
      .icache_areq_o(icache_areq_o),
      .icache_fetch_vaddr_i(icache_fetch_vaddr_i),
      .lsu_valid_i(lsu_valid_i),
      .lsu_paddr_i(lsu_paddr_i),
      .lsu_vaddr_i(lsu_vaddr_i),
      .lsu_exception_i(lsu_exception_i),
      .lsu_is_store_i(lsu_is_store_i),
      .lsu_valid_o(lsu_valid_o),
      .lsu_paddr_o(lsu_paddr_o),
      .lsu_exception_o(lsu_exception_o),
      .priv_lvl_i(priv_lvl_i),
      .v_i(v_i),
      .ld_st_priv_lvl_i(ld_st_priv_lvl_i),
      .ld_st_v_i(ld_st_v_i),
      .pmpcfg_i(pmpcfg_i),
      .pmpaddr_i(pmpaddr_i)
  );

  task automatic clear_inputs;
    begin
      clk_i = 1'b0;
      rst_ni = 1'b1;
      icache_areq_i = '0;
      icache_fetch_vaddr_i = '0;
      lsu_valid_i = 1'b0;
      lsu_paddr_i = '0;
      lsu_vaddr_i = '0;
      lsu_exception_i = '0;
      lsu_is_store_i = 1'b0;
      priv_lvl_i = riscv::PRIV_LVL_M;
      v_i = 1'b0;
      ld_st_priv_lvl_i = riscv::PRIV_LVL_M;
      ld_st_v_i = 1'b0;
      pmpcfg_i = '0;
      pmpaddr_i = '0;
    end
  endtask

  initial begin
    clear_inputs();
    rst_ni = 1'b0;
    #1ns;
    rst_ni = 1'b1;

    // Invalid fetches must not create a new access fault.
    clear_inputs();
    icache_areq_i.fetch_valid = 1'b0;
    icache_areq_i.fetch_paddr = 'h2000;
    icache_fetch_vaddr_i = 'h2000;
    #1ns;
    if (icache_areq_o.fetch_exception.valid !== 1'b0) begin
      $fatal(1, "invalid fetch generated an instruction exception");
    end

    // A page fault must keep priority over a later PMP access fault.
    clear_inputs();
    icache_areq_i.fetch_valid = 1'b1;
    icache_areq_i.fetch_paddr = 'h2000;
    icache_fetch_vaddr_i = 'h4000;
    icache_areq_i.fetch_exception.valid = 1'b1;
    icache_areq_i.fetch_exception.cause = riscv::INSTR_PAGE_FAULT;
    icache_areq_i.fetch_exception.tval = 'h4000;
    #1ns;
    if (icache_areq_o.fetch_exception.valid !== 1'b1) begin
      $fatal(1, "page fault lost its valid bit");
    end
    if (icache_areq_o.fetch_exception.cause !== riscv::INSTR_PAGE_FAULT) begin
      $fatal(1, "page fault was overwritten by cause %0d", icache_areq_o.fetch_exception.cause);
    end

    $display("TB_PASS");
    $finish;
  end
endmodule
EOF

