  ariane_pkg::alu_bypass_t alu_bypass_o;
  logic [CVA6Cfg.NrIssuePorts-1:0][CVA6Cfg.VLEN-1:0] rs1_forwarding_o;
  logic [CVA6Cfg.NrIssuePorts-1:0][CVA6Cfg.VLEN-1:0] rs2_forwarding_o;
  logic [CVA6Cfg.VLEN-1:0] pc_o;
  logic is_zcmt_o;
  logic is_compressed_instr_o;
  logic flu_ready_i;
  logic [CVA6Cfg.NrIssuePorts-1:0] alu_valid_o;
  logic [CVA6Cfg.NrIssuePorts-1:0] aes_valid_o;
  logic [CVA6Cfg.NrIssuePorts-1:0] branch_valid_o;
  logic [CVA6Cfg.NrIssuePorts-1:0][31:0] tinst_o;
  branchpredict_sbe_t branch_predict_o;
  logic lsu_ready_i;
  logic [CVA6Cfg.NrIssuePorts-1:0] lsu_valid_o;
  logic [CVA6Cfg.NrIssuePorts-1:0] mult_valid_o;
  logic fpu_ready_i;
  logic fpu_early_valid_i;
  logic [CVA6Cfg.NrIssuePorts-1:0] fpu_valid_o;
  logic [1:0] fpu_fmt_o;
  logic [2:0] fpu_rm_o;
  logic [CVA6Cfg.NrIssuePorts-1:0] alu2_valid_o;
  logic [CVA6Cfg.NrIssuePorts-1:0] csr_valid_o;
  logic [CVA6Cfg.NrIssuePorts-1:0] cvxif_valid_o;
  logic cvxif_ready_i;
  logic [31:0] cvxif_off_instr_o;
  logic [CVA6Cfg.XLEN-1:0] hart_id_i;
  logic x_issue_ready_i;
  x_issue_resp_t x_issue_resp_i;
  logic x_issue_valid_o;
  x_issue_req_t x_issue_req_o;
  logic x_register_ready_i;
  logic x_register_valid_o;
  x_register_t x_register_o;
  logic x_commit_valid_o;
  x_commit_t x_commit_o;
  logic x_transaction_accepted_o;
  logic x_transaction_rejected_o;
  logic x_issue_writeback_o;
  logic [CVA6Cfg.TRANS_ID_BITS-1:0] x_id_o;
  logic [CVA6Cfg.NrCommitPorts-1:0][4:0] waddr_i;
  logic [CVA6Cfg.NrCommitPorts-1:0][CVA6Cfg.XLEN-1:0] wdata_i;
  logic [CVA6Cfg.NrCommitPorts-1:0] we_gpr_i;
  logic [CVA6Cfg.NrCommitPorts-1:0] we_fpr_i;
  logic stall_issue_o;
  logic [CVA6Cfg.NrIssuePorts-1:0][CVA6Cfg.XLEN-1:0] rvfi_rs1_o;
  logic [CVA6Cfg.NrIssuePorts-1:0][CVA6Cfg.XLEN-1:0] rvfi_rs2_o;
  logic [5:0] orig_instr_aes_bits;

  issue_read_operands #(
      .CVA6Cfg(CVA6Cfg),
      .branchpredict_sbe_t(branchpredict_sbe_t),
      .fu_data_t(fu_data_t),
      .scoreboard_entry_t(scoreboard_entry_t),
      .forwarding_t(forwarding_t),
      .writeback_t(writeback_t),
      .rs3_len_t(rs3_len_t),
      .x_issue_req_t(x_issue_req_t),
      .x_issue_resp_t(x_issue_resp_t),
      .x_register_t(x_register_t),
      .x_commit_t(x_commit_t)
  ) dut (
      .clk_i,
      .rst_ni,
      .flush_i,
      .stall_i,
      .issue_instr_i,
      .issue_instr_i_prev,
      .orig_instr_i,
      .issue_instr_valid_i,
      .issue_ack_o,
      .fwd_i,
      .fu_data_o,
      .alu_bypass_o,
      .rs1_forwarding_o,
      .rs2_forwarding_o,
      .pc_o,
      .is_zcmt_o,
      .is_compressed_instr_o,
      .flu_ready_i,
      .alu_valid_o,
      .aes_valid_o,
      .branch_valid_o,
      .tinst_o,
      .branch_predict_o,
      .lsu_ready_i,
      .lsu_valid_o,
      .mult_valid_o,
      .fpu_ready_i,
      .fpu_early_valid_i,
      .fpu_valid_o,
      .fpu_fmt_o,
      .fpu_rm_o,
      .alu2_valid_o,
      .csr_valid_o,
      .cvxif_valid_o,
      .cvxif_ready_i,
      .cvxif_off_instr_o,
      .hart_id_i,
      .x_issue_ready_i,
      .x_issue_resp_i,
      .x_issue_valid_o,
      .x_issue_req_o,
      .x_register_ready_i,
      .x_register_valid_o,
      .x_register_o,
      .x_commit_valid_o,
      .x_commit_o,
      .x_transaction_accepted_o,
      .x_transaction_rejected_o,
      .x_issue_writeback_o,
      .x_id_o,
      .waddr_i,
      .wdata_i,
      .we_gpr_i,
      .we_fpr_i,
      .stall_issue_o,
      .rvfi_rs1_o,
      .rvfi_rs2_o,
      .orig_instr_aes_bits
  );

  always #5 clk_i = ~clk_i;

  task automatic clear_inputs();
    issue_instr_i = '{default: '0};
    issue_instr_i_prev = '{default: '0};
    orig_instr_i = '{default: 32'h0000_0013};
    issue_instr_valid_i = '0;
    fwd_i = '0;
    flush_i = 1'b0;
    stall_i = 1'b0;
    flu_ready_i = 1'b1;
    lsu_ready_i = 1'b1;
    fpu_ready_i = 1'b1;
    fpu_early_valid_i = 1'b0;
    cvxif_ready_i = 1'b1;
    hart_id_i = '0;
    x_issue_ready_i = 1'b1;
    x_issue_resp_i = '0;
    x_register_ready_i = 1'b1;
    waddr_i = '0;
    wdata_i = '0;
    we_gpr_i = '0;
    we_fpr_i = '0;
  endtask

  task automatic configure_consumer();
    issue_instr_valid_i[0] = 1'b1;
    issue_instr_i[0].fu = ariane_pkg::ALU;
    issue_instr_i[0].op = ariane_pkg::ADD;
    issue_instr_i[0].rs1 = 5'd5;
    issue_instr_i[0].rs2 = 5'd0;
    issue_instr_i[0].rd = 5'd6;
    issue_instr_i[0].trans_id = '0;
    issue_instr_i[0].result = 32'h0000_0001;
    issue_instr_i[0].valid = 1'b0;
    issue_instr_i[0].use_imm = 1'b1;
    issue_instr_i[0].use_zimm = 1'b0;
    issue_instr_i[0].use_pc = 1'b0;
    issue_instr_i[0].ex = '0;
    issue_instr_i[0].bp = '0;
    issue_instr_i_prev[0] = issue_instr_i[0];
  endtask

  task automatic configure_producer(input logic producer_has_exception);
    fwd_i.issue_pointer = '0;
    fwd_i.still_issued[3] = 1'b1;
    fwd_i.sbe[3].fu = ariane_pkg::ALU;
    fwd_i.sbe[3].op = ariane_pkg::ADD;
    fwd_i.sbe[3].rd = 5'd5;
    fwd_i.sbe[3].trans_id = 3;
    fwd_i.sbe[3].result = 32'hDEAD_BEEF;
    fwd_i.sbe[3].valid = 1'b1;
    fwd_i.sbe[3].ex.valid = producer_has_exception;
  endtask

  task automatic expect_blocked_exceptional_forward();
    clear_inputs();
    configure_consumer();
    configure_producer(1'b1);
    #1;
    if (issue_ack_o[0] !== 1'b0 || stall_issue_o !== 1'b1) begin
      $display("unexpected exceptional dependency behavior: issue_ack=%0b stall_issue=%0b", issue_ack_o[0], stall_issue_o);
      $fatal(1);
    end
  endtask

  task automatic expect_valid_forward();
    clear_inputs();
    configure_consumer();
    configure_producer(1'b0);
    #1;
    if (issue_ack_o[0] !== 1'b1 || stall_issue_o !== 1'b0) begin
      $display("unexpected valid dependency behavior: issue_ack=%0b stall_issue=%0b", issue_ack_o[0], stall_issue_o);
      $fatal(1);
    end
    if (rs1_forwarding_o[0] !== 32'hDEAD_BEEF) begin
      $display("unexpected forwarded operand: %08x", rs1_forwarding_o[0]);
      $fatal(1);
    end
  endtask

  initial begin
    clk_i = 1'b0;
    rst_ni = 1'b0;
    clear_inputs();
    #2;
    rst_ni = 1'b1;
    #2;

    expect_blocked_exceptional_forward();
    expect_valid_forward();

    $display("tb completed");
    $finish;
  end
endmodule
EOF

BUILD_LOG="$TB_DIR/build.log"
RUN_LOG="$TB_DIR/run.log"
OBJ_DIR="$TB_DIR/obj_dir"
SIM_BIN="$OBJ_DIR/Vtb"

set +e
"${VERILATOR_BIN[@]}" \
  --timing \
  --binary \
  --sv \
  --top-module tb \
  --Mdir "$OBJ_DIR" \
  -Wno-fatal \
  -Wno-BLKSEQ \
  -Wno-DECLFILENAME \
  -Wno-SELRANGE \
  -Wno-TIMESCALEMOD \
  -Wno-UNUSEDPARAM \
  -Wno-UNUSEDSIGNAL \
  -Wno-WIDTHTRUNC \
  -Wno-WIDTHEXPAND \
  -j "${NUM_JOBS:-4}" \
  -I/home/cva6/core/include \
  /home/cva6/core/include/config_pkg.sv \
  /home/cva6/core/include/cv32a6_imac_sv32_config_pkg.sv \
  /home/cva6/core/include/riscv_pkg.sv \
  /home/cva6/core/include/ariane_pkg.sv \
  /home/cva6/core/include/build_config_pkg.sv \
  /home/cva6/core/raw_checker.sv \
  /home/cva6/core/ariane_regfile_ff.sv \
  /home/cva6/core/ariane_regfile_fpga.sv \
  /home/cva6/core/cvxif_issue_register_commit_if_driver.sv \
  /home/cva6/core/issue_read_operands.sv \
  "$TB_DIR/tb.sv" \
  >"$BUILD_LOG" 2>&1
build_rc=$?

run_rc=$build_rc
if [[ $build_rc -eq 0 ]]; then
  "$SIM_BIN" >"$RUN_LOG" 2>&1
  run_rc=$?
fi
set -e

rc=$run_rc
echo "HWE_BENCH_RESULTS_START"
if [[ $rc -eq 0 ]]; then
  echo "TEST: $TB_NAME ... PASS"
else
  echo "TEST: $TB_NAME ... FAIL"
fi
echo "HWE_BENCH_RESULTS_END"

if [[ $rc -ne 0 ]]; then
  if [[ -f "$BUILD_LOG" ]]; then
    tail -n 80 "$BUILD_LOG"
  fi
  if [[ -f "$RUN_LOG" ]]; then
    tail -n 80 "$RUN_LOG"
  fi
fi

exit "$rc"

