tb_script:
#!/bin/bash
set -euo pipefail

cd /home/cva6

if [ -f /etc/cva6_bash_env ]; then
  # shellcheck disable=SC1091
  source /etc/cva6_bash_env
fi
if [ -f /etc/cva6_tools_path.sh ]; then
  # shellcheck disable=SC1091
  source /etc/cva6_tools_path.sh
fi

TEST_NAME="hfence_rd_decoder"
TB_DIR="/home/cva6/.tb_${TEST_NAME}"
BUILD_LOG="${TB_DIR}/build.log"
RUN_LOG="${TB_DIR}/run.log"
OBJ_DIR="${TB_DIR}/obj_dir"

rm -rf "${TB_DIR}"
mkdir -p "${TB_DIR}"

cat > "${TB_DIR}/tb_hfence_rd_decoder.sv" <<'SV'
module tb_hfence_rd_decoder;
  import ariane_pkg::*;

  function automatic config_pkg::cva6_user_cfg_t make_user_cfg();
    config_pkg::cva6_user_cfg_t cfg;
    cfg = cva6_config_pkg::cva6_cfg;
    cfg.CvxifEn = bit'(0);
    return cfg;
  endfunction

  localparam config_pkg::cva6_cfg_t CVA6Cfg = build_config_pkg::build_config(make_user_cfg());

  typedef struct packed {
    cf_t                     cf;
    logic [CVA6Cfg.VLEN-1:0] predict_address;
  } branchpredict_sbe_t;

  typedef struct packed {
    logic [CVA6Cfg.XLEN-1:0]  cause;
    logic [CVA6Cfg.XLEN-1:0]  tval;
    logic [CVA6Cfg.GPLEN-1:0] tval2;
    logic [31:0]              tinst;
    logic                     gva;
    logic                     valid;
  } exception_t;

  typedef struct packed {
    logic [CVA6Cfg.XLEN-1:0] mie;
    logic [CVA6Cfg.XLEN-1:0] mip;
    logic [CVA6Cfg.XLEN-1:0] mideleg;
    logic [CVA6Cfg.XLEN-1:0] hideleg;
    logic                    sie;
    logic                    global_enable;
  } irq_ctrl_t;

  typedef struct packed {
    logic [CVA6Cfg.XLEN-1:0] S_SW;
    logic [CVA6Cfg.XLEN-1:0] VS_SW;
    logic [CVA6Cfg.XLEN-1:0] M_SW;
    logic [CVA6Cfg.XLEN-1:0] S_TIMER;
    logic [CVA6Cfg.XLEN-1:0] VS_TIMER;
    logic [CVA6Cfg.XLEN-1:0] M_TIMER;
    logic [CVA6Cfg.XLEN-1:0] S_EXT;
    logic [CVA6Cfg.XLEN-1:0] VS_EXT;
    logic [CVA6Cfg.XLEN-1:0] M_EXT;
    logic [CVA6Cfg.XLEN-1:0] HS_EXT;
  } interrupts_t;

  typedef struct packed {
    logic [CVA6Cfg.VLEN-1:0]              pc;
    logic [CVA6Cfg.TRANS_ID_BITS-1:0]     trans_id;
    fu_t                                  fu;
    fu_op                                 op;
    logic [REG_ADDR_SIZE-1:0]             rs1;
    logic [REG_ADDR_SIZE-1:0]             rs2;
    logic [REG_ADDR_SIZE-1:0]             rd;
    logic [CVA6Cfg.XLEN-1:0]              result;
    logic                                 valid;
    logic                                 use_imm;
    logic                                 use_zimm;
    logic                                 use_pc;
    exception_t                           ex;
    branchpredict_sbe_t                   bp;
    logic                                 is_compressed;
    logic                                 is_macro_instr;
    logic                                 is_last_macro_instr;
    logic                                 is_double_rd_macro_instr;
    logic                                 vfp;
    logic                                 is_zcmt;
  } scoreboard_entry_t;

  localparam interrupts_t INTERRUPTS = '{
      S_SW: (CVA6Cfg.XLEN'(1) << (CVA6Cfg.XLEN - 1)) | CVA6Cfg.XLEN'(riscv::IRQ_S_SOFT),
      VS_SW: (CVA6Cfg.XLEN'(1) << (CVA6Cfg.XLEN - 1)) | CVA6Cfg.XLEN'(riscv::IRQ_VS_SOFT),
      M_SW: (CVA6Cfg.XLEN'(1) << (CVA6Cfg.XLEN - 1)) | CVA6Cfg.XLEN'(riscv::IRQ_M_SOFT),
      S_TIMER: (CVA6Cfg.XLEN'(1) << (CVA6Cfg.XLEN - 1)) | CVA6Cfg.XLEN'(riscv::IRQ_S_TIMER),
      VS_TIMER: (CVA6Cfg.XLEN'(1) << (CVA6Cfg.XLEN - 1)) | CVA6Cfg.XLEN'(riscv::IRQ_VS_TIMER),
      M_TIMER: (CVA6Cfg.XLEN'(1) << (CVA6Cfg.XLEN - 1)) | CVA6Cfg.XLEN'(riscv::IRQ_M_TIMER),
      S_EXT: (CVA6Cfg.XLEN'(1) << (CVA6Cfg.XLEN - 1)) | CVA6Cfg.XLEN'(riscv::IRQ_S_EXT),
      VS_EXT: (CVA6Cfg.XLEN'(1) << (CVA6Cfg.XLEN - 1)) | CVA6Cfg.XLEN'(riscv::IRQ_VS_EXT),
      M_EXT: (CVA6Cfg.XLEN'(1) << (CVA6Cfg.XLEN - 1)) | CVA6Cfg.XLEN'(riscv::IRQ_M_EXT),
      HS_EXT: (CVA6Cfg.XLEN'(1) << (CVA6Cfg.XLEN - 1)) | CVA6Cfg.XLEN'(riscv::IRQ_HS_EXT)
  };

  localparam logic [6:0] HFENCE_VVMA_FUNCT7 = 7'b0010001;
  localparam logic [6:0] HFENCE_GVMA_FUNCT7 = 7'b0110001;

  logic                          debug_req_i;
  logic [CVA6Cfg.VLEN-1:0]       pc_i;
  logic                          is_compressed_i;
  logic [15:0]                   compressed_instr_i;
  logic                          is_illegal_i;
  logic [31:0]                   instruction_i;
  logic                          is_macro_instr_i;
  logic                          is_last_macro_instr_i;
  logic                          is_double_rd_macro_instr_i;
  logic                          is_zcmt_i;
  logic [CVA6Cfg.XLEN-1:0]       jump_address_i;
  branchpredict_sbe_t            branch_predict_i;
  exception_t                    ex_i;
  logic [1:0]                    irq_i;
  irq_ctrl_t                     irq_ctrl_i;
  riscv::priv_lvl_t              priv_lvl_i;
  logic                          v_i;
  logic                          debug_mode_i;
  riscv::xs_t                    fs_i;
  riscv::xs_t                    vfs_i;
  logic [2:0]                    frm_i;
  riscv::xs_t                    vs_i;
  logic                          tvm_i;
  logic                          tw_i;
  logic                          vtw_i;
  logic                          tsr_i;
  logic                          hu_i;
  scoreboard_entry_t             instruction_o;
  logic [31:0]                   orig_instr_o;
  logic                          is_control_flow_instr_o;

  function automatic logic [31:0] encode_hfence(input logic [6:0] funct7, input logic [4:0] rd);
    return {funct7, 5'd0, 5'd0, 3'b000, rd, 7'b1110011};
  endfunction

  task automatic drive_common(input logic [31:0] instr_word, input riscv::priv_lvl_t priv_level);
    begin
      debug_req_i = 1'b0;
      pc_i = '0;
      is_compressed_i = 1'b0;
      compressed_instr_i = '0;
      is_illegal_i = 1'b0;
      instruction_i = instr_word;
      is_macro_instr_i = 1'b0;
      is_last_macro_instr_i = 1'b0;
      is_double_rd_macro_instr_i = 1'b0;
      is_zcmt_i = 1'b0;
      jump_address_i = '0;
      branch_predict_i = '0;
      ex_i = '0;
      irq_i = '0;
      irq_ctrl_i = '0;
      priv_lvl_i = priv_level;
      v_i = 1'b0;
      debug_mode_i = 1'b0;
      fs_i = riscv::Off;
      vfs_i = riscv::Off;
      frm_i = '0;
      vs_i = riscv::Off;
      tvm_i = 1'b0;
      tw_i = 1'b0;
      vtw_i = 1'b0;
      tsr_i = 1'b0;
      hu_i = 1'b0;
      #1;
    end
  endtask

  task automatic expect_illegal(
      input logic [31:0] instr_word,
      input riscv::priv_lvl_t priv_level,
      input string name
  );
    begin
      drive_common(instr_word, priv_level);
      if (!(instruction_o.ex.valid && instruction_o.ex.cause == riscv::ILLEGAL_INSTR)) begin
        $display("ILLEGAL check failed for %s: instr=%h valid=%0d cause=%0h op=%0d rd=%0d",
                 name, instr_word, instruction_o.ex.valid, instruction_o.ex.cause, instruction_o.op,
                 instruction_o.rd);
        $fatal(1);
      end
    end
  endtask

  task automatic expect_legal(
      input logic [31:0] instr_word,
      input riscv::priv_lvl_t priv_level,
      input fu_op expected_op,
      input string name
  );
    begin
      drive_common(instr_word, priv_level);
      if (instruction_o.ex.valid) begin
        $display("LEGAL check failed for %s: instr=%h valid=%0d cause=%0h op=%0d",
                 name, instr_word, instruction_o.ex.valid, instruction_o.ex.cause, instruction_o.op);
        $fatal(1);
      end
      if (instruction_o.op != expected_op) begin
        $display("OP check failed for %s: instr=%h expected_op=%0d got_op=%0d",
                 name, instr_word, expected_op, instruction_o.op);
        $fatal(1);
      end
    end
  endtask

  decoder #(
      .CVA6Cfg(CVA6Cfg),
      .branchpredict_sbe_t(branchpredict_sbe_t),
      .exception_t(exception_t),
      .irq_ctrl_t(irq_ctrl_t),
      .scoreboard_entry_t(scoreboard_entry_t),
      .interrupts_t(interrupts_t),
      .INTERRUPTS(INTERRUPTS)
  ) dut (
      .debug_req_i(debug_req_i),
      .pc_i(pc_i),
      .is_compressed_i(is_compressed_i),
      .compressed_instr_i(compressed_instr_i),
      .is_illegal_i(is_illegal_i),
      .instruction_i(instruction_i),
      .is_macro_instr_i(is_macro_instr_i),
      .is_last_macro_instr_i(is_last_macro_instr_i),
      .is_double_rd_macro_instr_i(is_double_rd_macro_instr_i),
      .is_zcmt_i(is_zcmt_i),
      .jump_address_i(jump_address_i),
      .branch_predict_i(branch_predict_i),
      .ex_i(ex_i),
      .irq_i(irq_i),
      .irq_ctrl_i(irq_ctrl_i),
      .priv_lvl_i(priv_lvl_i),
      .v_i(v_i),
      .debug_mode_i(debug_mode_i),
      .fs_i(fs_i),
      .vfs_i(vfs_i),
      .frm_i(frm_i),
      .vs_i(vs_i),
      .tvm_i(tvm_i),
      .tw_i(tw_i),
      .vtw_i(vtw_i),
      .tsr_i(tsr_i),
      .hu_i(hu_i),
      .instruction_o(instruction_o),
      .orig_instr_o(orig_instr_o),
      .is_control_flow_instr_o(is_control_flow_instr_o)
  );

  initial begin
    expect_illegal(encode_hfence(HFENCE_VVMA_FUNCT7, 5'd1), riscv::PRIV_LVL_M, "hfence_vvma_rd_nonzero");
    expect_illegal(encode_hfence(HFENCE_GVMA_FUNCT7, 5'd2), riscv::PRIV_LVL_S, "hfence_gvma_rd_nonzero");
    expect_legal(encode_hfence(HFENCE_VVMA_FUNCT7, 5'd0), riscv::PRIV_LVL_M, HFENCE_VVMA, "hfence_vvma_rd_zero");
    expect_legal(encode_hfence(HFENCE_GVMA_FUNCT7, 5'd0), riscv::PRIV_LVL_S, HFENCE_GVMA, "hfence_gvma_rd_zero");
    $display("hfence decoder checks passed");
    $finish;
  end
endmodule
SV

set +e
timeout 1200s verilator --binary --timing --top-module tb_hfence_rd_decoder \
